       NET.roster=coop?[{seat:0,name:'HOST',host:true},{seat:1,name:'ZQX MATE'}]:[];
       NET.up=coop?[{seat:1,n:1,age:0,sd:G.seed>>>0,tx:z.x,ty:z.y,tf:0,dn:0}]:[];
