  {v:'16.05',what:'teammate revives: as the host with a linked teammate down beside him, E held for the hire pick-up time sends the pick-up to that seat, and letting go early sends nothing (control: a teammate on his feet is never picked up); as the linked window, down, a pick-up from the host with the teammate beside him puts him on his feet at 40 percent, and one from a teammate far off does not',
   run:function(){
     if(!(window.__resetCfg&&window.__pinDefaults&&window.__startRaid&&window.__cleanProfile)||typeof NET!=='object'||!NET||typeof updatePlayer!=='function'||typeof netOnMsg!=='function') return 'SKIP: this fixture cannot stage a party raid';
     var bad=[], keepN={on:NET.on,role:NET.role,peers:NET.peers,upSeed:NET.upSeed,seat:NET.seat,up:NET.up,roster:NET.roster}, sent=[], p, i, rv, peer;
     function mk(seat){ return {state:'in',seat:seat,name:'ZQX',timers:[],dc:{readyState:'open',send:function(t){ sent.push(JSON.parse(t)); }}}; }
     // v16.11: held the way the loop holds it: a pick-up takes E for its step (netRevHold) and the loop hands it back after; one
     // step with E up at the end lets go, so the next hold starts a fresh pick-up
     function hold(sec){ for(var t=0;t<sec;t+=0.05){ keys['KeyE']=true; updatePlayer(0.05); if(G.netRevEat) G.netRevEat=0; } keys['KeyE']=false; updatePlayer(0.05); }
     function mate(seat,x,y,dn){ NET.up[seat]={seat:seat,x:x,y:y,f:0,tx:x,ty:y,tf:0,n:5,age:0,dn:dn?1:0,sd:NET.upSeed>>>0}; }
     try{
       __resetCfg(); __pinDefaults(0); __startRaid({mapIx:0,seed:4242}); keys={};
       p=G.player; G.sim=0; G.over=false;
       NET.on=true; NET.role='host'; NET.seat=0; peer=mk(1); NET.peers=[peer]; NET.upSeed=G.seed>>>0; NET.up=[];
       NET.roster=[{seat:0,name:'HOST',host:true},{seat:1,name:'ZQX MATE'}];
       // CONTROL: on his feet, nothing is sent however long E is held
       mate(1,p.x+30,p.y,false); sent.length=0; hold(4);
       if(sent.some(function(m){ return m.t==='rev'; })) bad.push('control: a teammate on his feet was picked up');
       mate(1,p.x+30,p.y,true); sent.length=0; hold(1.5);
       if(sent.some(function(m){ return m.t==='rev'; })) bad.push('E held 1.5 s picked the teammate up before the 3.2 s a hire takes');
       sent.length=0; hold(3.5);
       rv=sent.filter(function(m){ return m.t==='rev'; });
       if(rv.length!==1||rv[0].s!==1) bad.push('E held 3.5 s beside a downed teammate sent '+JSON.stringify(rv)+', not one pick-up for seat 1');
       // THE DOWNED WINDOW
       NET.role='join'; NET.seat=1; peer=mk(0); NET.peers=[peer]; NET.up=[];
       NET.roster=[{seat:0,name:'ZQX HOST',host:true},{seat:1,name:'ME'}];
       p.downed=true; p.hp=0; G.deathBeat=null;
       mate(0,p.x+500,p.y,false);
       netOnMsg(peer,JSON.stringify({t:'rev',s:1,by:0}));
       if(!p.downed) bad.push('a pick-up from a teammate 500 away put him on his feet');
       mate(0,p.x+30,p.y,false);
       var r2=netOnMsg(peer,JSON.stringify({t:'rev',s:1,by:0}));
       if(p.downed) bad.push('a pick-up from the teammate beside him left him down ('+r2+')');
       else if(p.hp!==Math.round(p.maxhp*0.4)) bad.push('picked up with '+p.hp+' health, not the 40 percent a hire gives');
     }
     finally{
       try{ keys={}; }catch(_k){}
       try{ NET.on=keepN.on; NET.role=keepN.role; NET.peers=keepN.peers||[]; NET.upSeed=keepN.upSeed; NET.seat=keepN.seat; NET.up=keepN.up||[]; NET.roster=keepN.roster||[]; }catch(_n){}
       try{ G=null; }catch(_g){}
       try{ __resetCfg(); }catch(_rc){}
       try{ __cleanProfile(); }catch(_cp){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'16.04',what:'pause, Superhot and the death slow-down in co-op: in a shared party raid with Superhot on and no input the world still runs, paused the world and the clock run on while he stands still with W held, and the death beat runs the world at full speed; control, the same window alone keeps the solo rules (Superhot freezes, pause stops the world)',
   run:function(){
     if(!(window.__resetCfg&&window.__pinDefaults&&window.__startRaid&&window.__cleanProfile&&window.__loop)||typeof NET!=='object'||!NET||typeof netInCount!=='function') return 'SKIP: this fixture cannot stage a party raid';
     var bad=[], keepN={on:NET.on,role:NET.role,peers:NET.peers,upSeed:NET.upSeed,seat:NET.seat}, keepSt=state, TS=1000, peer={state:'in',seat:1,name:'ZQX',timers:[],dc:{readyState:'open',send:function(){}}}, t0, x0, cl0;
     function frames(n){ for(var i=0;i<n;i++){ TS+=16; __loop(TS); } }
     function stage(party){
       __resetCfg(); __pinDefaults(0); __startRaid({mapIx:0,seed:4242});
       state='raid'; G.sim=0; G.over=false; G.deathBeat=null; G.paused=false; pauseOpen=false; keys={};
       CFG.superhot=1;
       NET.on=party; NET.role=party?'host':null; NET.seat=0; NET.peers=party?[peer]:[]; NET.upSeed=party?(G.seed>>>0):0;
       if(party){ NET.roster=[{seat:0,pid:'me',name:'HOST',host:true},{seat:1,pid:'zqxmate',name:'ZQX MATE'}]; NET.up=[]; NET.up[1]={seat:1,x:G.player.x+300,y:G.player.y,f:0,tx:G.player.x+300,ty:G.player.y,tf:0,n:5,age:0,dn:0,sd:NET.upSeed>>>0,pz:0,sa:1}; }   // v16.27: the world runs under a pause only while a teammate is up top and playing; this one is, acting
       frames(2);
     }
     try{
       // SOLO CONTROL
       stage(false);
       t0=G.t; frames(10); if(G.t!==t0) bad.push('control: alone with Superhot on and no input the world moved ('+t0+' to '+G.t+')');
       CFG.superhot=0; G.paused=true; t0=G.t; frames(10); if(G.t!==t0) bad.push('control: alone and paused the world moved');
       G.paused=false; G.over='abandon';
       // THE PARTY
       stage(true);
       if(!(netEntsHost&&netEntsHost())) return 'SKIP: the staged party raid does not read as the host world';
       t0=G.t; frames(10); if(!(G.t>t0)) bad.push('in a party raid with Superhot on and no input the world stood still, so one player froze it for everyone');
       CFG.superhot=0; G.paused=true; t0=G.t; cl0=G.timeLeft; x0=[G.player.x,G.player.y]; keys['KeyW']=true;
       frames(15);
       if(!(G.t>t0)) bad.push('paused in a party raid the world stood still');
       if(Math.hypot(G.player.x-x0[0],G.player.y-x0[1])>0.5) bad.push('paused in a party raid with W held he walked '+Math.hypot(G.player.x-x0[0],G.player.y-x0[1]).toFixed(1));
       keys={}; G.paused=false;
       G.deathBeat=5; t0=G.t; frames(10);
       if(!(G.t-t0>0.1)) bad.push('in a party raid the death beat slowed the shared world to '+(G.t-t0).toFixed(3)+' s over 10 frames');
       G.deathBeat=null;
     }
     finally{
       try{ keys={}; pauseOpen=false; if(G){ G.paused=false; G.deathBeat=null; } }catch(_k){}
       try{ NET.on=keepN.on; NET.role=keepN.role; NET.peers=keepN.peers||[]; NET.upSeed=keepN.upSeed; NET.seat=keepN.seat; }catch(_n){}
       try{ G=null; state=keepSt; }catch(_g){}
       try{ if(typeof state==='undefined'||state!=='hub') __hubEnter(); }catch(_he){}
       try{ __resetCfg(); }catch(_rc){}
       try{ __cleanProfile(); }catch(_cp){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'16.03',what:'a lightning flash shows you to them from farther, not across the whole map: an enemy facing you at 1.6 times its sight on open ground sees you in the flash and not without it (control), one at 3 times its sight does not see you even in the flash, and a sim step counts the flash down',
   run:function(){
     if(!(window.__resetCfg&&window.__pinDefaults&&window.__startRaid&&window.__cleanProfile)||typeof updateEnts!=='function'||typeof roofAt!=='function') return 'SKIP: this fixture cannot stage a raid';
     var bad=[], keepE=null, keepV=null, e=null, p, i, a, r;
     function look(d,flash){
       e.x=p.x+d; e.y=p.y; e.face=Math.PI; e.state='patrol'; e.alert=0; e.seenYou=false; e.blind=0; e.cd=9; e.overheat=0;
       G.lightning=flash; G.pCrouch=false; G.pConceal=1;
       try{ updateEnts(0.001); }catch(x){ bad.push('updateEnts threw: '+x); }
       return !!(e.seenYou||e.state==='chase'||e.alert>0);
     }
     try{
       __resetCfg(); __pinDefaults(0); __startRaid({mapIx:0,seed:4242});
       if(!G||!G.player) return 'SKIP: no raid staged';
       p=G.player; p.downed=false;
       for(i=0;i<G.ents.length&&!e;i++) if(G.ents[i].kind==='sentry'&&G.ents[i].rng>0) e=G.ents[i];
       if(!e) return 'SKIP: no sentry on this map';
       keepE=G.ents; keepV=G.vseg; G.ents=[e]; G.vseg=[];
       r=e.rng;
       for(a=0;a<40;a++){ if(!roofAt(p.x,p.y)&&!roofAt(p.x+r*1.6,p.y)&&!roofAt(p.x+r*3,p.y)) break; p.x+=137; p.y+=91; }
       if(roofAt(p.x,p.y)||roofAt(p.x+r*1.6,p.y)) return 'SKIP: no open ground found';
       if(look(r*1.6,0)) return 'SKIP: the sentry sees him at 1.6 times its sight without a flash, so this staging cannot tell';
       if(!look(r*1.6,0.3)) bad.push('in a lightning flash a sentry facing him on open ground at '+Math.round(r*1.6)+' (1.6 times its sight of '+r+') did not see him');
       if(look(r*3,0.3)) bad.push('in a lightning flash a sentry at '+Math.round(r*3)+' (3 times its sight) saw him, so the flash shows him across the map');
       G.sim=1; G.lightning=0.34;
       try{ simStep(0.15); }catch(x2){}
       if(!(G.lightning<0.34)) bad.push('a sim step left the flash at '+G.lightning+', so the bot would be seen for the rest of the storm');
     }
     finally{
       try{ if(keepE) G.ents=keepE; if(keepV) G.vseg=keepV; }catch(_k){}
       try{ G=null; keys={}; }catch(_g){}
       try{ __resetCfg(); }catch(_rc){}
       try{ __cleanProfile(); }catch(_cp){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'16.02',what:'partly cloudy does not hold: a weather turn into Partly Cloudy on the last turn of a raid keeps one turn back for the break it announces; control, a last turn into rain leaves none',
