       try{ if(g&&keep){ g.tod=keep.tod; g.wx=keep.wx; g.wxNext=keep.wxNext; g.wxT=keep.wxT; g.mapOpen=keep.mapOpen; } }catch(_g){}
       try{ if(g&&!g.over) __endRaid('abandon'); }catch(_e){}
       try{ if(snap) __applyLoaded(snap); }catch(_r){}
