       var p=g.player, i, LK=null, C=null, O=null, PX=null;
       var corners=[{x:90,y:90},{x:WORLD_W-90,y:90},{x:90,y:WORLD_H-90},{x:WORLD_W-90,y:WORLD_H-90}];
