     function last(t){ var o=posts(t); return o.length?o[o.length-1]:null; }
     // A state as the other window would hand it over.
     function fwd(ix,own,down,axes){ var p=[], v=[], q; for(q=0;q<17;q++){ p.push(down.indexOf(q)>=0?1:0); v.push(down.indexOf(q)>=0?1:0); } return {t:'pad',pair:PAIR,ix:ix,own:own,p:p,v:v,a:axes||[0,0,0,0]}; }
     function downs(){ var o=[], q; for(q=0;q<(PAD.prev||[]).length;q++) if(PAD.prev[q]) o.push(q); return o.join(','); }
     function same(a,b){ var q; if(!a||!b||a.length!==b.length) return false; for(q=0;q<a.length;q++) if(Math.abs(a[q]-b[q])>1e-6) return false; return true; }
     function frame(){ pollPad(); }
     try{
       __topClear();
       try{ __hubEnter(); }catch(_h){}
       closeAll();   // a fresh profile opens the welcome window
       try{ var pbx=document.getElementById('pausebox'); if(pbx&&pbx.classList.contains('on')){ try{ togglePauseBox(false); }catch(_tp){} if(pbx.classList.contains('on')){ pbx.classList.remove('on'); pauseOpen=false; } } }catch(_pb){}
       if(typeof state==='undefined'||state!=='hub'||!HB||!HB.player) return skip('the Undercroft floor is not up here');
       if(padOpenModal()) return skip('a panel is open over the floor, so the reader would work the panel and not the floor');
       try{ navigator.getGamepads=function(){ return []; }; stubbed=(navigator.getGamepads!==NG); }catch(_s){}
       if(!stubbed){ try{ navigator.getGamepads=NG; }catch(_r0){} return skip('this browser will not let the pad be faked'); }
       try{ document.hasFocus=function(){ hf.n++; return hf.v; }; hfStub=(document.hasFocus()===true&&hf.n===1); hf.n=0; }catch(_hf){ hfStub=false; }
       if(!hfStub) return skip('this browser will not let the focus be faked');
       netReset();
       say2=function(){};
       for(var k0 in keys) keys[k0]=false;
       keepP={x:HB.player.x,y:HB.player.y,face:HB.player.face};
       keepPad={on:PAD.on,aSpent:PAD.aSpent,announced:PAD.announced,ax:PAD.ax,mrep:PAD.mrep,mx:PAD.mx,my:PAD.my,prev:(PAD.prev||[]).slice()};
       keepNet={padIx:NET.padIx,padOther:NET.padOther};
       lsWas={h:ls(KH),p:ls(KP)};
       rng0=RNGS;

       // ONE: THE ROW. Hidden outside a same machine mode, shown in one, and it cycles the pick and keeps it.
       NET.same=''; renderParty();
       if(shown(g('partypad'))) bad.push('the CONTROLLER row shows outside a same machine mode');
       NET.same='host'; NET.pair=PAIR; NET.mode='coop'; NET.bc=ch; NET.padIx=-1; NET.padOther=-1; NET.padFwd=null;
       renderParty();
       if(!shown(g('partypad'))) bad.push('the CONTROLLER row is not shown in a same machine mode');
       if(txt(g('partypadbtn')).indexOf('CONTROLLER')<0) bad.push('the CONTROLLER row does not name a controller: '+txt(g('partypadbtn')));
       ch.posted=[];
       var c1=netPadCycle(); renderParty();
       if(c1!==0||NET.padIx!==0) bad.push('one press on the CONTROLLER row did not pick controller 1 (pick '+NET.padIx+')');
       if(txt(g('partypadbtn')).indexOf('CONTROLLER 1')<0) bad.push('the row does not read CONTROLLER 1 after one press: '+txt(g('partypadbtn')));
       var pk=last('padpick');
       if(!pk||pk.pair!==PAIR||pk.ix!==0) bad.push('the pick was not told to the other window ('+js(pk)+')');
       if(ls(KH)!=='0') bad.push('the host pick is not kept under '+KH+' (it holds '+ls(KH)+')');
       netPadCycle(); netPadCycle(); netPadCycle();
       if(NET.padIx!==3) bad.push('four presses did not reach controller 4 (pick '+NET.padIx+')');
       netPadCycle();
       if(NET.padIx!==-1||ls(KH)!==null) bad.push('a fifth press did not come round to none (pick '+NET.padIx+', kept '+ls(KH)+')');

       // THE PICK IS TOLD. The real same machine pick (the second window, the code maker and the channel stood in) reads the
       // pick kept from last time and tells the player 2 window; a ready from player 2 is answered with it again; the real
       // player 2 boot reads its own kept pick and tells the host, and ready stays the last word of the boot.
       NET.bc=null; NET.same=''; NET.pair=''; NET.mode='';
       netReset();
       spied=true;
       window.open=function(){ return {closed:false}; };
       window.BroadcastChannel=BC;
       netHost=function(){ return {then:function(){}}; };
       NET.start=function(){};
       try{ localStorage.setItem(KH,'2'); localStorage.setItem(KP,'1'); }catch(_lk){}
       var k1=netSamePick('coop',function(){});
       if(k1!=='opened'||NET.same!=='host'||!NET.bc||chans.length!==1) bad.push('the stand-in same machine pick did not open ('+k1+', same '+NET.same+', channels '+chans.length+')');
       else {
         if(NET.padIx!==2) bad.push('the host pick kept from last time was not read at the pick (pick '+NET.padIx+')');
         var t1=lastOf(chans[0].posted,'padpick');
         if(!t1||t1.ix!==2||t1.pair!==NET.pair) bad.push('the host pick was not told to the player 2 window at the pick ('+js(t1)+')');
         chans[0].posted=[];
         netSameOnMsg({t:'ready',pair:NET.pair});
         var t2=lastOf(chans[0].posted,'padpick');
         if(!t2||t2.ix!==2) bad.push('a ready from player 2 was not answered with the host pick ('+js(chans[0].posted)+')');
       }
       netReset();
       if(NET.same||NET.bc||NET.padOther!==-1) bad.push('ending the party did not let go of the channel and the other window pick (same '+NET.same+', other '+NET.padOther+')');
       chans=[];
       var b2=netSameBootP2(PAIR,'coop');
       if(b2!=='ready'||chans.length!==1) bad.push('the stand-in player 2 boot did not get ready ('+b2+', channels '+chans.length+')');
       else {
         if(NET.padIx!==1) bad.push('the player 2 pick kept from last time was not read at boot (pick '+NET.padIx+')');
         var t3=lastOf(chans[0].posted,'padpick'), rd=chans[0].posted.length?chans[0].posted[chans[0].posted.length-1]:null;
         if(!t3||t3.ix!==1||t3.pair!==PAIR) bad.push('the player 2 pick was not told to the host at boot ('+js(t3)+')');
         if(!rd||rd.t!=='ready') bad.push('ready is not the last word of the player 2 boot ('+js(rd)+')');
       }
       NET.bc=null; NET.same=''; NET.pair=''; NET.mode='';   // a player 2 boot keeps its channel across netReset; the stand-in is let go by hand
       netReset();
       unspy();
       try{ localStorage.removeItem(KH); localStorage.removeItem(KP); }catch(_lk2){}
       // Back to the stand-in state for the frames below.
       NET.same='host'; NET.pair=PAIR; NET.mode='coop'; NET.bc=ch; NET.padIx=-1; NET.padOther=-1; NET.padFwd=null;

       // TWO: THE HOST IN FRONT. With no pick it plays no pad and hands player 2 the first connected pad; with controller 1
       // picked it plays that and hands player 2 controller 2, with its buttons, its trigger and its sticks, never its own.
       var P0=pad(0,[3],[0,0,0,0]), P1=pad(1,[0,5],[0.6,-0.4,0,0],{6:0.4});
       pads([P0,P1]); hf.v=true; hf.n=0; ch.posted=[];
       NET.padIx=-1; NET.padOther=-1; NET.padFwd=null;
       frame();
       if(!PAD.on||!PAD.prev[0]||PAD.prev[3]) bad.push('the host with no controller picked does not play the second controller, his rule of 2026-09-27 (buttons down '+downs()+')');   // v16.35
       if(keys.KeyF) bad.push('the host with no controller picked holds a key from the player 2 pad (F '+!!keys.KeyF+')');   // v16.35
       var h1=posts('pad');
       if(h1.length!==1) bad.push('one frame of the host in front handed over '+h1.length+' states, not one');
       else if(h1[0].pair!==PAIR||h1[0].ix!==0||h1[0].own!==-1||!h1[0].p||h1[0].p[3]!==1||h1[0].p[0]!==0) bad.push('the host with no pick did not hand player 2 the first connected pad, controller 1 with Y down ('+js(h1[0])+')');
       netPadSet(0); ch.posted=[];
       frame();
       if(!PAD.on) bad.push('the host that picked controller 1 plays no pad');
       if(!keys.KeyF||keys.KeyE||keys.KeyT) bad.push('the host that picked controller 1 does not hold its Y as F, or holds E or T from the other pad (F '+!!keys.KeyF+', E '+!!keys.KeyE+', T '+!!keys.KeyT+')');
       if(!PAD.prev[3]||PAD.prev[0]||PAD.prev[5]) bad.push('the host reads the wrong pad: buttons down '+downs()+', not 3');
       var h2=posts('pad');
       if(h2.length!==1) bad.push('the host that picked controller 1 handed over '+h2.length+' states in one frame, not one');
       else {
         var m2=h2[0];
         if(m2.ix!==1||m2.own!==0) bad.push('the host hands player 2 pad '+m2.ix+' (its own is '+m2.own+'), not controller 2');
         if(!m2.p||m2.p[0]!==1||m2.p[5]!==1||m2.p[3]!==0) bad.push('the state handed over does not carry controller 2 with A and RB down and Y up ('+js(m2.p)+')');
         if(!m2.v||Math.abs(m2.v[6]-0.4)>0.011) bad.push('the state handed over does not carry the trigger part way ('+js(m2.v)+')');
         if(!same(m2.a,[0.6,-0.4,0,0])) bad.push('the state handed over does not carry the sticks ('+js(m2.a)+')');
       }
       frame(); frame();
       if(posts('pad').length!==3) bad.push('three frames in front handed over '+posts('pad').length+' states, not three');
       // A pick both windows made goes to the host; a pick of a pad that is not there is handed nothing; another pair is ignored.
       if(netSameOnMsg({t:'padpick',pair:PAIR,ix:0})!=='padpick'||NET.padOther!==0) bad.push('the player 2 pick did not reach the host (other '+NET.padOther+')');
       ch.posted=[]; frame();
       var h3=last('pad');
       if(!h3||h3.ix!==1||!PAD.prev[3]) bad.push('with both windows picking controller 1 the host did not keep it and hand player 2 controller 2 ('+js(h3)+', host down '+downs()+')');
       netSameOnMsg({t:'padpick',pair:PAIR,ix:2}); ch.posted=[]; frame();
       if(posts('pad').length) bad.push('player 2 picked controller 3, which is not plugged in, and was handed '+js(last('pad'))+' instead of nothing');
       if(netSameOnMsg({t:'padpick',pair:'zqxotherpair',ix:1})!=='ignored'||NET.padOther!==2) bad.push('a pick from another pair code was taken (other '+NET.padOther+')');
       netSameOnMsg({t:'padpick',pair:PAIR,ix:1}); ch.posted=[]; frame();
       if(!last('pad')||last('pad').ix!==1) bad.push('player 2 picking controller 2 is not handed it ('+js(last('pad'))+')');
       // The host not in front: nothing goes out, its own read is not played, and a state handed over by player 2 is.
       hf.v=false; ch.posted=[]; NET.padOther=-1;
       frame();
       if(posts('pad').length) bad.push('the host not in front handed over a state');
       if(PAD.on||keys.KeyF) bad.push('the host not in front plays its own read (on '+PAD.on+', F '+!!keys.KeyF+')');
       var r1=netSameOnMsg(fwd(0,1,[2],[0,0.5,0,0]));
       if(r1!=='pad'||NET.padOther!==1) bad.push('a state handed over by player 2 was not kept ('+r1+', other '+NET.padOther+')');
       frame();
       if(!PAD.on||!keys.KeyR||keys.KeyF||!PAD.prev[2]||PAD.prev[3]) bad.push('the host not in front does not play the state handed over: on '+PAD.on+', R '+!!keys.KeyR+', F '+!!keys.KeyF+', down '+downs());
       if(!PAD.ax||Math.abs(PAD.ax[1]-0.5)>1e-6||Math.abs(PAD.my-padAxis(0.5))>1e-6) bad.push('the sticks handed over did not reach the pad fields (ax '+js(PAD.ax)+', my '+PAD.my+')');
       if(netSameOnMsg(fwd(1,1,[2]))!=='padown') bad.push('a state from the other window own pad was kept');
       if(netSameOnMsg(fwd(1,0,[2]))!=='padnot') bad.push('a state from a pad the host did not pick was kept');
       if(netSameOnMsg(fwd(0,1,[2]))!=='pad') bad.push('control: a state from the pad the host picked was refused');
       NET.padFwd.at-=1;
       frame();
       if(PAD.on||keys.KeyR) bad.push('a state handed over a second ago is still played (on '+PAD.on+', R '+!!keys.KeyR+')');
       NET.padIx=-1;
       if(netSameOnMsg(fwd(0,1,[2]))!=='pad') bad.push('the host with no pick refused the second controller player 2 handed over');   // v16.35

       // THREE: PLAYER 2. Not in front: its own read is ignored, the state handed over drives the reader and the keys it holds
       // are the ones the buttons handed over hold. In front: its own pad wins and the host is handed its pad.
       NET.same='p2'; NET.padIx=-1; NET.padOther=-1; NET.padFwd=null; ch.posted=[]; hf.v=false;
       var OWN=pad(0,[2],[-0.7,0,0,0]);
       pads([OWN]);
       frame();
       if(PAD.on||keys.KeyR||keys.KeyE) bad.push('player 2 not in front plays its own read (on '+PAD.on+', R '+!!keys.KeyR+')');
       var r2=netSameOnMsg(fwd(1,0,[0,3],[0.6,-0.4,0,0]));
       if(r2!=='pad'||NET.padOther!==0) bad.push('the state the host handed over was not kept ('+r2+', other '+NET.padOther+')');
       frame();
       if(!PAD.on) bad.push('player 2 not in front does not play the state handed over');
       if(!keys.KeyE||!keys.KeyF||keys.KeyR) bad.push('the buttons handed over do not hold their keys (E '+!!keys.KeyE+', F '+!!keys.KeyF+'), or the own pad X holds R ('+!!keys.KeyR+')');
       if(!PAD.prev[0]||!PAD.prev[3]||PAD.prev[2]) bad.push('the reader shows buttons '+downs()+' down, not 0 and 3 handed over');
       if(!same(PAD.ax,[0.6,-0.4,0,0])||Math.abs(PAD.mx-padAxis(0.6))>1e-6||Math.abs(PAD.my-padAxis(-0.4))>1e-6) bad.push('the sticks handed over did not reach the pad fields (ax '+js(PAD.ax)+', mx '+PAD.mx+', my '+PAD.my+')');
       if(posts('pad').length) bad.push('player 2 not in front handed a state to the host');
       if(netSameOnMsg(fwd(0,0,[0]))!=='padown') bad.push('player 2 kept a state from the host own pad');
       if(netSameOnMsg({t:'pad',pair:'zqxotherpair',ix:1,own:0,p:[1],v:[1],a:[0,0,0,0]})!=='ignored') bad.push('player 2 kept a state from another pair');
       if(netSameOnMsg({t:'pad',pair:PAIR,ix:1,own:0,p:[1,0],v:[1],a:[0,0,0,0]})!=='bad') bad.push('a state with buttons and values of different lengths was kept');
       // In front: the own pad wins (controller 2, since the host holds controller 1), the state handed over is dropped, and
       // the host is handed controller 1 with nothing of player 2 in it.
       hf.v=true; ch.posted=[];
       pads([pad(0,[4],[0,0,0,0]),pad(1,[2],[-0.7,0,0,0])]);
       frame();
       if(!PAD.on||!keys.KeyR||keys.KeyE||keys.KeyF||!PAD.prev[2]||PAD.prev[0]||PAD.prev[3]||PAD.prev[4]) bad.push('player 2 in front does not play its own pad, controller 2 (on '+PAD.on+', R '+!!keys.KeyR+', E '+!!keys.KeyE+', down '+downs()+')');
       if(!same(PAD.ax,[-0.7,0,0,0])) bad.push('player 2 in front does not read its own sticks (ax '+js(PAD.ax)+')');
       if(NET.padFwd) bad.push('player 2 in front kept the state handed over earlier');
       var h4=posts('pad');
       if(h4.length!==1||h4[0].ix!==0||h4[0].own!==-1||!h4[0].p||h4[0].p[4]!==1||h4[0].p[2]!==0) bad.push('player 2 in front did not hand the host its controller 1 with LB down and nothing of its own ('+js(h4)+')');
       netPadSet(1); renderParty();
       if(ls(KP)!=='1'||NET.padIx!==1||!last('padpick')||last('padpick').ix!==1) bad.push('the player 2 pick is not kept under '+KP+' and told to the host (kept '+ls(KP)+', pick '+NET.padIx+')');
       if(txt(g('partypadbtn')).indexOf('CONTROLLER 2')<0) bad.push('the player 2 row does not read CONTROLLER 2: '+txt(g('partypadbtn')));
       ch.posted=[]; frame();
       if(!keys.KeyR||keys.KeyE||!last('pad')||last('pad').ix!==0) bad.push('player 2 that picked controller 2 does not play it and hand the host controller 1 (R '+!!keys.KeyR+', handed '+js(last('pad'))+')');
       netPadSet(0); ch.posted=[]; frame();
       if(!keys.KeyR||PAD.prev[4]||!last('pad')||last('pad').ix!==0) bad.push('player 2 picking the host controller 1 was given it: down '+downs()+', handed '+js(last('pad')));
       netPadSet(1); hf.v=false; pads([OWN]); ch.posted=[];
       if(netSameOnMsg(fwd(0,-1,[0]))!=='padnot') bad.push('player 2 that picked controller 2 kept a state from controller 1');
       if(netSameOnMsg(fwd(1,0,[0]))!=='pad') bad.push('control: player 2 that picked controller 2 refused a state from it');
       frame();
       if(!keys.KeyE||keys.KeyR) bad.push('player 2 not in front with a pick does not play the state handed over (E '+!!keys.KeyE+', R '+!!keys.KeyR+')');
       if(posts('pad').length) bad.push('player 2 not in front with a pick handed a state to the host');
       netPadSet(-1);
       if(ls(KP)!==null) bad.push('a pick of none left '+KP+' behind ('+ls(KP)+')');

       // FOUR: CONTROL. Outside a same machine mode nothing is handed over, focus is never asked, a state handed over is not
       // played, and the first connected pad is read as before.
       NET.same=''; NET.pair=''; NET.padFwd=null; ch.posted=[]; hf.n=0; hf.v=false;
       pads([P0,P1]);
       frame();
       if(!PAD.on||!keys.KeyF||keys.KeyE||!PAD.prev[3]||PAD.prev[0]) bad.push('control: outside a same machine mode the first connected pad is not read as before (on '+PAD.on+', F '+!!keys.KeyF+', down '+downs()+')');
       if(ch.posted.length) bad.push('control: outside a same machine mode a state was handed over');
       if(hf.n) bad.push('control: outside a same machine mode the reader asked about focus '+hf.n+' times');
       NET.pair=PAIR;
       if(netSameOnMsg(fwd(0,1,[2]))==='pad'||NET.padFwd) bad.push('control: outside a same machine mode a state handed over was kept');
       if(RNGS!==rng0) bad.push('the seeded stream moved from '+rng0+' to '+RNGS+' through the hand-over');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ NET.bc=null; NET.same=''; NET.pair=''; NET.mode=''; NET.padFwd=null; NET.padOther=(keepNet?keepNet.padOther:-1); NET.padIx=(keepNet?keepNet.padIx:-1); }catch(_n){}
       try{ netReset(); }catch(_nr){}
       try{ unspy(); }catch(_us){}
       try{ NET.pick=''; NET.p2url=''; }catch(_np){}
       try{ netModeMsg(''); }catch(_mm){}
       try{ if(lsWas){ if(lsWas.h===null) localStorage.removeItem(KH); else localStorage.setItem(KH,lsWas.h); if(lsWas.p===null) localStorage.removeItem(KP); else localStorage.setItem(KP,lsWas.p); } }catch(_l){}
       try{ if(hfStub){ if(hadHF) document.hasFocus=oHF; else delete document.hasFocus; } }catch(_h2){}
       try{ if(stubbed){ navigator.getGamepads=function(){ return []; }; pollPad(); } }catch(_p0){}
       try{ padRelease(); }catch(_pr){}
       try{ navigator.getGamepads=NG; }catch(_p){}
       try{ if(keepPad){ PAD.on=keepPad.on; PAD.aSpent=keepPad.aSpent; PAD.announced=keepPad.announced; PAD.ax=keepPad.ax; PAD.mrep=keepPad.mrep; PAD.mx=keepPad.mx; PAD.my=keepPad.my; PAD.prev=keepPad.prev; } }catch(_kp){}
       try{ for(var k3 in keys) keys[k3]=false; }catch(_k3){}
       try{ if(keepP&&HB&&HB.player){ HB.player.x=keepP.x; HB.player.y=keepP.y; HB.player.face=keepP.face; HB.eLock=true; } }catch(_hp){}
       try{ renderParty(); }catch(_rp){}
       try{ closeAll(); }catch(_ca){}
       try{ say2=_s2; }catch(_s2e){}
       try{ __topClear(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'15.76',what:'the title opens on a mode menu and two windows on one PC pair up: the menu shows five rows in his order and wording (1 PLAYER, 2 PLAYER CO-OP (SAME MACHINE), 2 PLAYER CO-OP (SERVER), 2 PLAYER PVP (SAME MACHINE), PVP (SERVER)) with the two server rows greyed and marked coming later, the first row being the old start button; 1 PLAYER runs the old start with the net section off, no window opened, no channel made and no peer connection made; a same machine row with the second window blocked keeps the title up, sets no mode and shows the sentence with RETRY, and RETRY with the window allowed records the address of this page with p2=1, the mode and the pair code, makes the channel, makes this copy the host and runs the start; the arrows step the highlight down the rows past the greyed ones and wrap, ENTER presses the highlighted row and with none highlighted starts 1 PLAYER, a faked controller lands on 1 PLAYER, steps down to the co-op row and presses it with A, and B and ESC leave the title as it is; ?p2=1 picks the player 2 save key, a save under it leaves the main save, the save pointer and the save in play untouched, and the pointer lock holds for it; the handshake carried on a stand-in channel reaches a roster of two on the host and on the player 2 side, a word with another pair code is ignored, and the seeded stream never moves (multiplayer build 3)',
   run:function(){
     // THE MENU IS THERE. Without it there is no way to pick a mode, so the old build fails here rather than skips.
     var mm=document.getElementById('modemenu'), t=document.getElementById('title');
     if(!mm||!t||typeof NET==='undefined'||!NET||typeof netSamePick!=='function'||typeof netSameOnMsg!=='function'||typeof netSameBootP2!=='function'||
        typeof netSameHostDone!=='function'||typeof netSameJoinDone!=='function'||typeof netP2Of!=='function'||typeof netP2Key!=='function'||
        typeof netModeOf!=='function'||typeof netPairOf!=='function'||typeof netSaveLocked!=='function'||typeof netTitleMove!=='function'||typeof netTitleEnter!=='function')
       return 'this build has no mode menu on the title screen (no #modemenu, no netSamePick, no netSameOnMsg, no netSameBootP2 and no player 2 save key), so the first thing a player picks is not the mode and two windows on one PC cannot pair up';
     if(typeof netOnMsg!=='function'||typeof netStartJoin!=='function'||typeof netReset!=='function'||typeof renderParty!=='function') return 'this build has no net section under the mode menu';
     if(typeof G!=='undefined'&&G&&!G.over) return 'SKIP: a raid is running, and the mode is picked on the title';
     if(!window.__hubEnter) return 'SKIP: this fixture cannot reach the Undercroft floor';
     var bad=[], PCB=window.__pcBoot||null, pcb0=PCB?PCB.made:0, made0=NET.made, rng0=null, keepP=null, keepPad=null, i;
     var wasOn=t.classList.contains('on'), _s2=say2, NG=navigator.getGamepads, stubbed=false, S0=SKEY, kP=null, lsWas=null;
     var oOpen=window.open, hadBC=('BroadcastChannel' in window), oBC=window.BroadcastChannel, oH=netHost, oJ=netJoin, oA=netAccept, oStart=NET.start, oNP2=(typeof NETP2!=='undefined')?NETP2:undefined;
     var opens=[], chans=[], calls={host:0,join:0,accept:0,start:0,msg:0}, openRet=null, codes={join:'',accept:''}, spied=false;
     var MAIN='salvagerun:profile', AS='salvagerun:activeSlot', mo=document.getElementById('partymode');
     var g=function(id){ return document.getElementById(id); };
     function ls(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } }
     function skip(m){ return bad.length?(bad.join('; ')+' (then SKIP: '+m+')'):('SKIP: '+m); }
     function stop(){ return bad.join('; '); }
     function txt(el){ return String((el&&el.textContent)||'').replace(/\s+/g,' ').replace(/^ | $/g,''); }
     function shown(el){ return !!el&&el.style.display!=='none'; }
     function lastPost(){ var c=NET.bc; return (c&&c.posted&&c.posted.length)?c.posted[c.posted.length-1]:null; }
     function js(o){ return JSON.stringify(o); }
     // A stand-in link that speaks the protocol and records what it is sent. Never a real connection.
     function fake(){
       var f={id:-1,pc:null,state:'open',seat:-1,pid:'',name:'',timers:[],sent:[]};
       f.dc={readyState:'open',send:function(x){ f.sent.push(String(x)); },close:function(){}};
       return f;
     }
     // A stand-in channel: records what is posted, and a check hands it words through its onmessage.
     function BC(name){ this.name=String(name); this.posted=[]; this.onmessage=null; this.closed=false; chans.push(this); }
     BC.prototype.postMessage=function(m){ this.posted.push(m); };
     BC.prototype.close=function(){ this.closed=true; };
     // A code maker that never resolves, so nothing runs after the check has put everything back.
     function pending(){ return {then:function(){}}; }
     function padWith(down){
       var bts=[],q;
       for(q=0;q<17;q++) bts.push({pressed:(q===down),value:(q===down)?1:0,touched:(q===down)});
       var fk={connected:true,id:'probe pad',index:0,mapping:'standard',timestamp:1,axes:[0,0,0,0],buttons:bts};
       navigator.getGamepads=function(){ return [fk]; };
     }
     function keyOn(code){
       window.dispatchEvent(new KeyboardEvent('keydown',{code:code,key:code,bubbles:true,cancelable:true}));
       window.dispatchEvent(new KeyboardEvent('keyup',{code:code,key:code,bubbles:true}));
     }
     function closeAll(){ [].forEach.call(document.querySelectorAll('.modal.on'),function(m){ m.classList.remove('on'); }); }
     function noFocus(){ try{ padSetFocus(null); PAD.focus=null; }catch(_f){} }
     try{
       __topClear();
       try{ __hubEnter(); }catch(_h){}
       closeAll();   // a fresh profile opens the welcome window
       try{ var pbx=document.getElementById('pausebox'); if(pbx&&pbx.classList.contains('on')){ try{ togglePauseBox(false); }catch(_tp){} if(pbx.classList.contains('on')){ pbx.classList.remove('on'); pauseOpen=false; } } }catch(_pb){}
       if(typeof state==='undefined'||!HB||!HB.player) return skip('the Undercroft floor is not up here');
       netReset();
       say2=function(){};
       for(var k0 in keys) keys[k0]=false;
       keepP={x:HB.player.x,y:HB.player.y,face:HB.player.face};
       rng0=RNGS;
       // THE STAND-INS: no window opens, no channel is real, no code is made.
       spied=true;
       window.open=function(u,nm,ft){ opens.push({url:String(u),name:nm,feat:ft}); return openRet; };
       window.BroadcastChannel=BC;
       netHost=function(){ calls.host++; return pending(); };
       netJoin=function(c){ calls.join++; codes.join=String(c); return pending(); };
       netAccept=function(c){ calls.accept++; codes.accept=String(c); return pending(); };
       NET.start=function(){ calls.start++; };

       // ONE: THE ROWS, in his order and wording, the server rows greyed and marked coming later, the first row the old start.
       var rows=mm.querySelectorAll('button[data-mode]'), want=['1 PLAYER','2 PLAYER CO-OP (SAME MACHINE)','2 PLAYER CO-OP (SERVER)','2 PLAYER PVP (SAME MACHINE)','PVP (SERVER)'];
       if(rows.length!==5) bad.push('the mode menu has '+rows.length+' rows, not five');
       for(i=0;i<Math.min(rows.length,5);i++) if(txt(rows[i])!==want[i]) bad.push('row '+(i+1)+' reads '+txt(rows[i])+', not '+want[i]);
       if(rows.length===5){
         if(!rows[2].disabled||!rows[4].disabled) bad.push('the two server rows are not greyed out');
         if(rows[0].disabled||rows[1].disabled||rows[3].disabled) bad.push('a row that plays today is greyed out');
         if(txt(rows[2].parentNode).toLowerCase().indexOf('coming later')<0||txt(rows[4].parentNode).toLowerCase().indexOf('coming later')<0) bad.push('a greyed server row is not marked coming later beside it');
         if(rows[0].id!=='titlestart') bad.push('the first row is not the old start button (its id is '+rows[0].id+'), so the pad focus and ENTER no longer land on it');
         if(!g('modecoop')||!g('modepvp')||g('modecoop').getAttribute('data-mode')!=='coop'||g('modepvp').getAttribute('data-mode')!=='pvp') bad.push('the two same machine rows are not #modecoop and #modepvp with their modes');
       }
       if(!g('modemsg')||!g('moderetry')) bad.push('the title has no sentence or RETRY for a blocked second window');
       if(!mo) bad.push('the PARTY window has no line naming the mode');

       // TWO: 1 PLAYER IS THE OLD START. The title goes, the floor is up, and the net section did nothing at all.
       t.classList.add('on'); noFocus();
       g('titlestart').click();
       if(t.classList.contains('on')) bad.push('1 PLAYER did not take the title down');
       if(state!=='hub') bad.push('1 PLAYER did not put him on the Undercroft floor (state '+state+')');
       if(NET.on||NET.role!==null||NET.mode||NET.same||NET.pair) bad.push('1 PLAYER switched the net section on: on '+NET.on+', role '+NET.role+', mode '+NET.mode+', same '+NET.same);
       if(opens.length) bad.push('1 PLAYER opened a second window');
       if(chans.length) bad.push('1 PLAYER made a channel between windows');
       if(calls.host||calls.join||calls.accept) bad.push('1 PLAYER made an invite or reply code');
       if(NET.made!==made0||(PCB&&PCB.wrapped&&PCB.made!==pcb0)) bad.push('1 PLAYER made a peer connection');
       closeAll();
       // And ENTER with nothing highlighted is the same start.
       t.classList.add('on'); noFocus();
       keyOn('Enter');
       if(t.classList.contains('on')) bad.push('ENTER on the title with nothing highlighted did not start 1 PLAYER');
       if(NET.on||NET.mode||opens.length||chans.length) bad.push('ENTER on the title with nothing highlighted ran net code');
       closeAll();

       // THREE: A SAME MACHINE ROW. Blocked first: the title stays, no mode is set, the sentence and RETRY show.
       t.classList.add('on'); noFocus();
       openRet=null;
       var r1=netSamePick('coop');
       if(r1!=='blocked') bad.push('with the second window blocked the pick said '+r1+', not blocked');
       if(NET.mode||NET.same||NET.on) bad.push('with the second window blocked the mode was set anyway: mode '+NET.mode+', same '+NET.same+', on '+NET.on);
       if(!t.classList.contains('on')) bad.push('with the second window blocked the title went away');
       if(calls.start) bad.push('with the second window blocked the start ran anyway');
       if(!shown(g('modemsg'))||!txt(g('modemsg'))) bad.push('with the second window blocked no sentence is shown on the title');
       else if(txt(g('modemsg')).toLowerCase().indexOf('popup')<0) bad.push('the blocked sentence does not tell him to allow the popup: '+txt(g('modemsg')));
       if(!shown(g('moderetry'))) bad.push('with the second window blocked RETRY is not offered');
       if(chans.length) bad.push('with the second window blocked a channel was made anyway');
       // RETRY with the window allowed: the address, the mode, the host, the channel, the start.
       var win={closed:false}, opened=opens.length;
       openRet=win;
       g('moderetry').click();
       var o=opens.length>opened?opens[opens.length-1]:null, base=String(location.href).split('#')[0].split('?')[0];
       if(!o) bad.push('RETRY did not open the second window');
       else {
         if(o.url.indexOf(base+'?')!==0) bad.push('the second window is not this page: '+o.url);
         if(!(/[?&]p2=1(&|$)/).test(o.url)) bad.push('the second window address has no p2=1: '+o.url);
         if(!(/[?&]mode=coop(&|$)/).test(o.url)) bad.push('the second window address does not carry the mode picked: '+o.url);
         if(!NET.pair||NET.pair.length<4||!(/[?&]pair=[a-z0-9]{4,16}(&|$)/).test(o.url)||o.url.indexOf('pair='+NET.pair)<0) bad.push('the second window address does not carry the pair code '+NET.pair+': '+o.url);
         if(o.url!==NET.p2url) bad.push('the address recorded on the net section is not the one opened');
       }
       if(NET.mode!=='coop'||NET.same!=='host'||!NET.on||NET.role!=='host'||NET.p2win!==win) bad.push('after RETRY this copy is not the host in co-op: mode '+NET.mode+', same '+NET.same+', on '+NET.on+', role '+NET.role);
       if(chans.length!==1||NET.bc!==chans[0]) bad.push('after RETRY there is not one channel between the windows ('+chans.length+' made)');
       else if(typeof chans[0].onmessage!=='function') bad.push('the channel has nothing listening on it');
       if(calls.host!==1) bad.push('after RETRY the invite code was made '+calls.host+' times, not once');
       if(calls.start!==1) bad.push('after RETRY the title start ran '+calls.start+' times, not once');
       if(shown(g('modemsg'))||shown(g('moderetry'))) bad.push('after RETRY the blocked sentence or RETRY is still shown');
       if(NET.made!==made0||(PCB&&PCB.wrapped&&PCB.made!==pcb0)) bad.push('the check itself made a peer connection, which it must never do');
       renderParty();
       if(mo&&(!shown(mo)||txt(mo).indexOf('CO-OP')<0||txt(mo).indexOf('SAME MACHINE')<0)) bad.push('the PARTY window does not name the mode: '+txt(mo));
       // PVP is the other same machine row, and only the mode value differs.
       netReset();
       if(NET.mode||NET.same||NET.pair||NET.bc||!chans[0].closed) bad.push('ending the party did not let go of the mode, the pair code and the channel');
       var r2=netSamePick('pvp');
       if(r2!=='opened'||NET.mode!=='pvp'||!(/[?&]mode=pvp(&|$)/).test(String(NET.p2url))) bad.push('the PVP row did not set the pvp mode ('+r2+', mode '+NET.mode+', '+NET.p2url+')');
       renderParty();
       if(mo&&txt(mo).indexOf('PVP')<0) bad.push('the PARTY window does not name the pvp mode: '+txt(mo));

       // FOUR: THE HANDSHAKE ON THE CHANNEL, host side. The invite code goes out when made and again when player 2 is ready,
       // a reply code is taken with netAccept, a word with another pair code is ignored, and the hello makes a roster of two.
       var ch=NET.bc, pair=NET.pair, CO='PTY1o'+'pzqxinvite', CA='PTY1a'+'pzqxreply';
       if(!ch||typeof ch.onmessage!=='function'){ bad.push('the pvp pick made no channel to carry the handshake'); return stop(); }
       var oMsg=netSameOnMsg; netSameOnMsg=function(){ calls.msg++; return oMsg.apply(null,arguments); };
       ch.posted=[];
       var d1=netSameHostDone({code:CO}), p1=lastPost();
       if(d1!=='offer'||!p1||p1.t!=='offer'||p1.pair!==pair||p1.mode!=='pvp'||p1.code!==CO) bad.push('the invite code made did not go out on the channel with the pair code and the mode ('+d1+', '+js(p1)+')');
       ch.posted=[];
       ch.onmessage({data:{t:'ready',pair:'zqxwrongpair'}});
       if(calls.msg!==1) bad.push('a word on the channel did not reach netSameOnMsg through the channel');
       if(ch.posted.length) bad.push('a ready from another pair code was answered');
       NET.pend={state:'offer'}; NET.code=CO;
       var d2=netSameOnMsg({t:'ready',pair:pair}), p2=lastPost();
       if(d2!=='offer'||!p2||p2.t!=='offer'||p2.code!==CO) bad.push('a ready from player 2 did not send the invite code out again ('+d2+', '+js(p2)+')');
       NET.pend=null; NET.code='';
       var d3=netSameOnMsg({t:'answer',pair:'zqxwrongpair',code:CA});
       if(d3!=='ignored'||calls.accept) bad.push('a reply code with another pair code was taken ('+d3+')');
       var d4=netSameOnMsg({t:'answer',pair:pair,code:CA});
       if(d4!=='accept'||calls.accept!==1||codes.accept!==CA) bad.push('the reply code on the channel was not taken with netAccept ('+d4+', taken '+calls.accept+' times, code '+codes.accept+')');
       if(netSameOnMsg({t:'answer',pair:pair,code:7})!=='bad') bad.push('a reply that is not a code was taken');
       var f1=fake(); NET.peers.push(f1);
       var h1=netOnMsg(f1,js({t:'hello',proto:NET.proto,ver:VER,pid:'f1f1f1f1',name:'ZQX PLAYER TWO'}));
       if(h1!=='welcome'||NET.roster.length!==2||f1.seat!==1) bad.push('after the handshake the hello did not make a roster of two on the host ('+h1+', '+NET.roster.length+')');
       var d5=netSameOnMsg({t:'fail',pair:pair,why:'zqx no link'});
       if(d5!=='fail'||String(NET.err).indexOf('zqx no link')<0) bad.push('a failure said by player 2 is not shown on the host ('+d5+', '+NET.err+')');
       netReset();
       if(NET.same||NET.bc||!ch.closed||NET.on) bad.push('ending the party did not close the channel');

       // FIVE: THE PLAYER 2 SIDE. Booted with a pair code and a mode, it says ready, takes the invite code with netJoin, adopts
       // the mode the host says, posts its reply code, and reads the welcome back as seat 1 of two.
       chans=[];
       var b1=netSameBootP2('zqxpair22','coop');
       if(b1!=='ready'||NET.same!=='p2'||NET.pair!=='zqxpair22'||NET.mode!=='coop') bad.push('the player 2 boot did not get ready ('+b1+', same '+NET.same+', pair '+NET.pair+', mode '+NET.mode+')');
       var c2=NET.bc, r0=lastPost();
       if(chans.length!==1||!c2||!r0||r0.t!=='ready'||r0.pair!=='zqxpair22') bad.push('the player 2 window did not tell the host it is ready on the channel ('+js(r0)+')');
       if(netSameOnMsg({t:'offer',pair:'zqxother',mode:'coop',code:CO})!=='ignored'||calls.join) bad.push('player 2 took an invite code from another pair');
       var j1=netSameOnMsg({t:'offer',pair:'zqxpair22',mode:'pvp',code:CO});
       if(j1!=='join'||calls.join!==1||codes.join!==CO) bad.push('the invite code on the channel was not taken with netJoin ('+j1+', taken '+calls.join+' times)');
       if(NET.mode!=='pvp') bad.push('player 2 did not take the mode the host says ('+NET.mode+')');
       if(c2) c2.posted=[];
       var j2=netSameJoinDone({code:CA}), a2=lastPost();
       if(j2!=='answer'||!a2||a2.t!=='answer'||a2.pair!=='zqxpair22'||a2.code!==CA) bad.push('the reply code did not go back on the channel ('+j2+', '+js(a2)+')');
       var j3=netSameJoinDone({err:'zqx bad code'}), a3=lastPost();
       if(j3!=='err'||!a3||a3.t!=='fail'||String(a3.why).indexOf('zqx bad code')<0) bad.push('a failed join is not said to the host on the channel ('+j3+', '+js(a3)+')');
       netStartJoin();
       var fh=fake(); fh.seat=0; NET.peers.push(fh);
       var w1=netOnMsg(fh,js({t:'welcome',you:1,ver:VER,roster:[{seat:0,pid:'aaaaaaaa',name:'ZQX HOST',host:true},{seat:1,pid:'bbbbbbbb',name:'ZQX ME',host:false}]}));
       if(w1!=='welcome'||NET.seat!==1||NET.roster.length!==2) bad.push('player 2 handed the welcome does not read seat 1 of two ('+w1+', seat '+NET.seat+', '+NET.roster.length+')');
       netReset();
       netSameOnMsg=oMsg;
       if(RNGS!==rng0) bad.push('the seeded stream moved from '+rng0+' to '+RNGS+' through the handshake');

       // SIX: THE PLAYER 2 SAVE KEY. ?p2=1 is read off the address, the key is its own, and a save under it touches nothing else.
       if(!netP2Of('?p2=1')||!netP2Of('?mode=coop&p2=1&pair=abcd')) bad.push('?p2=1 is not read off the address');
       if(netP2Of('')||netP2Of('?p2=0')||netP2Of('?p2=12')||netP2Of('?xp2=1')||netP2Of('?netslot=A')) bad.push('control: an address without p2=1 picks the player 2 save');
       if(netModeOf('?p2=1&mode=pvp&pair=abcd')!=='pvp'||netModeOf('?mode=coop')!=='coop'||netModeOf('?mode=zzz')!==''||netModeOf('')!=='') bad.push('the mode is not read off the address');
       if(netPairOf('?pair=abcd1234')!=='abcd1234'||netPairOf('?p2=1&pair=zq12&mode=coop')!=='zq12'||netPairOf('?pair=AB')!==''||netPairOf('')!=='') bad.push('the pair code is not read off the address');
       kP=netP2Key();
       if(kP===MAIN||kP===S0||kP===netSlotKey('A')||kP===netSlotKey('B')||kP.indexOf(MAIN+':')!==0||kP.indexOf(':net')>=0) bad.push('the player 2 save key '+kP+' is not a key of its own beside '+MAIN);
       if(typeof NETP2!=='boolean') bad.push('the page does not read NETP2 off its address (it is '+typeof NETP2+')');
       else {
         NETP2=true; var l1=netSaveLocked(); NETP2=oNP2;
         if(!l1) bad.push('the save pointer lock does not hold for the player 2 window');
         if(!NETSLOT&&!oNP2&&netSaveLocked()) bad.push('control: the save pointer lock holds for an ordinary copy');
       }
       if((typeof NETSLOT!=='undefined'&&NETSLOT)||oNP2) return skip('this page was itself opened with ?netslot or ?p2=1, so the main save cannot be told apart here');
       lsWas={main:ls(MAIN),as:ls(AS),own:ls(S0),p2:ls(kP)};
       SKEY=kP; saveProfile(); var lsP=ls(kP); SKEY=S0;
       var dP=null; try{ dP=JSON.parse(lsP); }catch(_p){}
       if(!dP||typeof dP.credits!=='number') bad.push('a save made under ?p2=1 wrote no readable save under '+kP);
       if(ls(MAIN)!==lsWas.main) bad.push('a save made under ?p2=1 changed the main save '+MAIN);
       if(ls(AS)!==lsWas.as) bad.push('a save made under ?p2=1 moved the save pointer '+AS);
       if(ls(S0)!==lsWas.own) bad.push('a save made under ?p2=1 changed the save this page plays, '+S0);

       // SEVEN: KEYBOARD AND CONTROLLER. The arrows step the highlight down the rows past the greyed ones and wrap, ENTER
       // presses the highlighted row; a faked controller lands on 1 PLAYER, steps down to the co-op row and presses it with A;
       // B and ESC leave the title as it is.
       t.classList.add('on'); noFocus(); calls.start=0; opens=[]; chans=[];
       keyOn('ArrowDown');
       if(PAD.focus!==g('modecoop')) bad.push('ArrowDown on the title did not move the highlight to the co-op row (it is on '+(PAD.focus?txt(PAD.focus):'nothing')+')');
       else if(!g('modecoop').classList.contains('padfocus')) bad.push('the highlighted row is not drawn highlighted');
       keyOn('ArrowDown');
       if(PAD.focus!==g('modepvp')) bad.push('a second ArrowDown did not step past the greyed server row to the pvp row (it is on '+(PAD.focus?txt(PAD.focus):'nothing')+')');
       keyOn('ArrowDown');
       if(PAD.focus!==g('titlestart')) bad.push('a third ArrowDown did not wrap to 1 PLAYER (it is on '+(PAD.focus?txt(PAD.focus):'nothing')+')');
       keyOn('ArrowUp');
       if(PAD.focus!==g('modepvp')) bad.push('ArrowUp from 1 PLAYER did not wrap to the pvp row');
       keyOn('KeyW');
       if(PAD.focus!==g('modecoop')) bad.push('W did not move the highlight up to the co-op row');
       keyOn('Enter');
       if(NET.mode!=='coop'||opens.length!==1||calls.start!==1) bad.push('ENTER on the highlighted co-op row did not pick co-op (mode '+NET.mode+', windows '+opens.length+', starts '+calls.start+')');
       if(!(/[?&]mode=coop(&|$)/).test(opens.length?opens[0].url:'')) bad.push('ENTER on the co-op row opened the wrong address: '+(opens.length?opens[0].url:'none'));
       netReset(); closeAll();
       // The controller, when the title is laid out for the pad to work it.
       t.classList.add('on'); noFocus(); calls.start=0; opens=[];
       try{ navigator.getGamepads=function(){ return []; }; stubbed=(navigator.getGamepads!==NG); }catch(_s){}
       var pf=(typeof padFocusables==='function')?padFocusables(t):[];
       if(stubbed&&typeof pollPad==='function'&&typeof PAD!=='undefined'&&pf.indexOf(g('titlestart'))>=0&&pf.indexOf(g('modecoop'))>=0){
         keepPad={aSpent:PAD.aSpent,announced:PAD.announced,ax:PAD.ax,mrep:PAD.mrep};
         padWith(-1); pollPad(); pollPad();
         if(PAD.focus!==g('titlestart')) bad.push('the pad focus on the title lands on '+(PAD.focus?txt(PAD.focus):'nothing')+', not 1 PLAYER');
         padWith(13); pollPad(); padWith(-1); pollPad();
         if(PAD.focus!==g('modecoop')) bad.push('D-pad down from 1 PLAYER lands on '+(PAD.focus?txt(PAD.focus):'nothing')+', not the co-op row');
         padWith(1); pollPad(); padWith(-1); pollPad();
         if(!t.classList.contains('on')||NET.mode||opens.length) bad.push('B on the title changed something: title '+t.classList.contains('on')+', mode '+NET.mode+', windows '+opens.length);
         if(PAD.focus===g('modecoop')){
           padWith(0); pollPad(); padWith(-1); pollPad();
           if(NET.mode!=='coop'||opens.length!==1||calls.start!==1) bad.push('A on the highlighted co-op row did not pick co-op (mode '+NET.mode+', windows '+opens.length+', starts '+calls.start+')');
         }
       }
       netReset(); closeAll();
       // ESC on the document, with the title up: nothing happens.
       t.classList.add('on'); noFocus();
       document.dispatchEvent(new KeyboardEvent('keydown',{code:'Escape',key:'Escape',bubbles:true,cancelable:true}));
       document.dispatchEvent(new KeyboardEvent('keyup',{code:'Escape',key:'Escape',bubbles:true}));
       if(!t.classList.contains('on')) bad.push('ESC took the title away');
       if(NET.on||NET.mode||document.querySelector('.modal.on')) bad.push('ESC on the title changed something');
       if(RNGS!==rng0) bad.push('the seeded stream moved from '+rng0+' to '+RNGS+' while the mode menu was worked');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ netReset(); }catch(_n){}
       try{ NET.pick=''; NET.p2url=''; }catch(_np){}
       try{ if(spied){ window.open=oOpen; if(hadBC) window.BroadcastChannel=oBC; else { try{ delete window.BroadcastChannel; }catch(_db){ window.BroadcastChannel=undefined; } } netHost=oH; netJoin=oJ; netAccept=oA; NET.start=oStart; } }catch(_r){}
       try{ if(typeof NETP2!=='undefined'&&oNP2!==undefined) NETP2=oNP2; }catch(_n2){}
       try{ SKEY=S0; }catch(_k){}
       try{ if(kP&&lsWas){ if(lsWas.p2===null) localStorage.removeItem(kP); else localStorage.setItem(kP,lsWas.p2); } }catch(_l){}
       try{ netModeMsg(''); }catch(_mm){}
       try{ closeAll(); }catch(_ca){}
       try{ navigator.getGamepads=function(){ return []; }; pollPad(); }catch(_p0){}
       try{ padSetFocus(null); PAD.focus=null; PAD.focusIx=-1; PAD.focusMd=null; PAD.aSpent=0; padRelease(); }catch(_pr){}
       try{ navigator.getGamepads=NG; }catch(_p){}
       try{ if(keepPad){ PAD.aSpent=keepPad.aSpent; PAD.announced=keepPad.announced; PAD.ax=keepPad.ax; PAD.mrep=keepPad.mrep; } }catch(_kp){}
       try{ for(var k3 in keys) keys[k3]=false; }catch(_k3){}
       try{ if(keepP&&HB&&HB.player){ HB.player.x=keepP.x; HB.player.y=keepP.y; HB.player.face=keepP.face; HB.eLock=true; } }catch(_hp){}
       try{ if(wasOn) t.classList.add('on'); else t.classList.remove('on'); }catch(_t){}
       try{ say2=_s2; }catch(_s2e){}
       try{ __topClear(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'15.75',what:'the party sees each other on the Undercroft floor, and solo play is untouched: with the party off a floor frame draws exactly the operators it drew before and calls none of the net floor code, and a floor update sends nothing and eases nobody, even with a friend left in the list behind a stand-in link that was let in; with the party on the floor update ticks the net floor code, with the PARTY window open too, and sends where he stands (x, y, facing and walking, his look in the first packet) about ten times a second on the fast channel when it is open and the reliable one when not; the host files a friend under the seat of his link whatever seat he claims, keeps his look to rack ids, passes him on to the other friend and never back, refuses a position that is not a number and one from a link that never said hello, eases him toward a new spot rather than jumping, and draws him once with the operator body in his own fit and hair where he stands, sorted with the player, with his name over him, the rest of the frame exactly as solo; a joining copy files the host and the other friend and ignores its own seat, a seat outside the roster and a position with no seat; a bye, a lost link or a roster without him takes him off the floor, and the seeded stream never moves (multiplayer build 2)',
   run:function(){
     // THE FLOOR CODE IS THERE. Without it two linked copies never see each other, so the old build fails here rather than skips.
     if(typeof NET==='undefined'||!NET||typeof netOnMsg!=='function'||typeof netStartHost!=='function'||typeof netStartJoin!=='function'||
        typeof netReset!=='function'||typeof netDrop!=='function')
       return 'this build has no net section, so nobody else can be drawn on the Undercroft floor';
     if(typeof netHubTick!=='function'||typeof netDrawPeers!=='function'||typeof netDrawPeer!=='function')
       return 'this build draws nobody else on the Undercroft floor: there is no netHubTick to send where he stands and no netDrawPeers or netDrawPeer to draw the others, so two linked copies cannot see each other';
     if(!NET.floor||typeof NET.floor.length!=='number') return 'the net section keeps no list of who stands where on the floor (NET.floor)';
     if(typeof G!=='undefined'&&G&&!G.over) return 'SKIP: a raid is running, and the party meets on the Undercroft floor';
     if(!window.__hubEnter) return 'SKIP: this fixture cannot reach the Undercroft floor';
     var bad=[], rng0=null, i, k, ops=[], texts=[], pm=document.getElementById('partymodal');
     var oOp=drawOp, oCrowd=(typeof tickHubCrowd==='function')?tickHubCrowd:null, oTick=netHubTick, oPeers=netDrawPeers, oPeer=netDrawPeer;
     var oTags=(typeof netDrawTags==='function')?netDrawTags:null, _s2=say2, calls={tick:0,peers:0,peer:0,tags:0};
     var keepP=null, keepH=null, fillOwn=false, oFill=null, spied=false, SAYT=(typeof HUBSAY_T==='number')?HUBSAY_T:null;
     function skip(m){ return bad.length?(bad.join('; ')+' (then SKIP: '+m+')'):('SKIP: '+m); }
     function stop(){ return bad.join('; '); }
     // A stand-in link that speaks the protocol and records what it is sent. Never a real connection.
     function fake(){
       var f={id:-1,pc:null,state:'open',seat:-1,pid:'',name:'',timers:[],sent:[]};
       f.dc={readyState:'open',send:function(x){ f.sent.push(String(x)); },close:function(){}};
       return f;
     }
     // And its fast channel, open, recording apart from the reliable one.
     function withFast(f){ f.fs=[]; f.fc={readyState:'open',send:function(x){ f.fs.push(String(x)); },close:function(){}}; return f; }
     function js(o){ return JSON.stringify(o); }
     function sts(list){ var out=[], q, j; for(j=0;j<(list||[]).length;j++){ q=null; try{ q=JSON.parse(list[j]); }catch(_j){} if(q&&q.t==='st') out.push(q); } return out; }
     function lastOf(a){ return a.length?a[a.length-1]:null; }
     function sig(list){
       var out=[], j, o;
       for(j=0;j<list.length;j++){ o=list[j]; out.push([(+o.x).toFixed(2),(+o.y).toFixed(2),(+o.f||0).toFixed(3),o.mode,o.hero?1:0].join(',')); }
       return out.join('|');
     }
     function drawnAs(own){ var out=[], j; for(j=0;j<ops.length;j++) if(own&&ops[j].own===own) out.push(ops[j]); return out; }
     function drawnBut(own){ var out=[], j; for(j=0;j<ops.length;j++) if(ops[j].own!==own) out.push(ops[j]); return out; }
     function painted(t){ return texts.join('|').indexOf(t)>=0; }
     function near1(o,x,y){ return !!o&&Math.abs(o.x-x)<=1&&Math.abs(o.y-y)<=1; }
     function xy(o){ return o?((+o.x).toFixed(1)+','+(+o.y).toFixed(1)):'nowhere'; }
     function home(){ var q=HB.player; q.x=keepP.x; q.y=keepP.y; q.face=keepP.face; q.moving=keepP.moving; q.rollT=keepP.rollT; q.bob=keepP.bob; HB.t=keepH.t; }
     function frame(){
       ops=[]; texts=[];
       try{ drawHubWorld(0); }catch(e){ bad.push('a floor frame threw: '+(e&&e.message||e)); }
     }
     try{
       __topClear();
       try{ __hubEnter(); }catch(_h){}
       [].forEach.call(document.querySelectorAll('.modal.on'),function(m){ m.classList.remove('on'); });   // a fresh profile opens the welcome window
       try{ var pbx=document.getElementById('pausebox'); if(pbx&&pbx.classList.contains('on')){ try{ togglePauseBox(false); }catch(_tp){} if(pbx.classList.contains('on')){ pbx.classList.remove('on'); pauseOpen=false; } } }catch(_pb){}
       if(typeof state==='undefined'||state!=='hub'||!HB||!HB.player||!wc) return skip('the Undercroft floor is not up here');
       netReset();
       say2=function(){};   // who joined is said on the floor; kept off it here
       for(k in keys) keys[k]=false;
       keepP={x:HB.player.x,y:HB.player.y,face:HB.player.face,moving:HB.player.moving,rollT:HB.player.rollT,bob:HB.player.bob};
       keepH={t:HB.t,near:HB.near,eLock:HB.eLock};
       rng0=RNGS;
       // THE SPIES: every operator drawn, every string painted on the floor canvas, every call into the net floor code.
       fillOwn=Object.prototype.hasOwnProperty.call(wc,'fillText'); oFill=wc.fillText;
       spied=true;
       drawOp=function(x,y,face,ph,coat,pk,mz,mode,iv,st){
         ops.push({x:x,y:y,f:face,mode:String(mode),coat:coat,hero:!!(st&&st.hero),hair:st?st.hair:undefined,own:(st&&st.own)||null});
         return oOp.apply(null,arguments);
       };
       if(oCrowd) tickHubCrowd=function(){};
       netHubTick=function(){ calls.tick++; return oTick.apply(null,arguments); };
       netDrawPeers=function(){ calls.peers++; return oPeers.apply(null,arguments); };
       netDrawPeer=function(){ calls.peer++; return oPeer.apply(null,arguments); };
       if(oTags) netDrawTags=function(){ calls.tags++; return oTags.apply(null,arguments); };
       wc.fillText=function(t){ texts.push(String(t)); return oFill.apply(wc,arguments); };

       // ONE: SOLO PLAY. With no party a floor frame calls none of the net floor code. The first frame settles anyone the
       // floor would still push out of a wall; the second is the solo frame every later frame is held to.
       frame();
       frame();
       var soloSig=sig(ops), soloN=ops.length;
       if(!soloN) return skip('the floor drew no operator at all, so there is nothing to compare');
       if(calls.peers||calls.peer||calls.tags) bad.push('with no party a floor frame still called into the net floor code ('+calls.peers+' list, '+calls.peer+' body, '+calls.tags+' names)');
       // A friend left in the list with the party off: staged through the real handlers, then the party switched off under him.
       netStartHost();
       var fl=fake(); NET.peers.push(fl);
       var al=netOnMsg(fl,js({t:'hello',proto:NET.proto,ver:VER,pid:'1e11e11e',name:'ZQX LEFT BEHIND'}));
       var sl=netOnMsg(fl,js({t:'st',x:211.5,y:233.5,f:0.5,m:1,r:0}));
       var gl=NET.floor[fl.seat]||null;
       if(al!=='welcome'||sl!=='state'||!gl){ bad.push('could not stage a friend on the floor through the real handlers (his hello said '+al+', his position said '+sl+')'); return stop(); }
       NET.on=false;
       calls={tick:0,peers:0,peer:0,tags:0}; fl.sent=[];
       gl.tx=gl.x+40; gl.ty=gl.y+30;
       var glx=gl.x, gly=gl.y;
       updateHubWorld(1/60); updateHubWorld(0.25);
       home();
       frame();
       if(calls.tick) bad.push('with the party off a floor update still called netHubTick ('+calls.tick+' times)');
       if(calls.peers||calls.peer||calls.tags) bad.push('with the party off and a friend still in the list a floor frame called into the net floor code ('+calls.peers+' list, '+calls.peer+' body, '+calls.tags+' names)');
       if(sts(fl.sent).length) bad.push('with the party off a floor update still sent where he stands: '+fl.sent[0]);
       if(gl.x!==glx||gl.y!==gly) bad.push('with the party off a floor update still eased the friend left in the list');
       if(sig(ops)!==soloSig) bad.push('with the party off and a friend left in the list the floor frame drew '+ops.length+' operators, not the '+soloN+' of the solo frame'+(drawnAs(gl).length?' (the friend among them)':''));
       if(painted('ZQX LEFT BEHIND')) bad.push('with the party off the name of a friend left in the list is still painted');
       var dl=[];
       if((oPeers(dl)||0)!==0||dl.length) bad.push('netDrawPeers with the party off still puts '+dl.length+' on the floor');
       if((oTick(0.5)||0)!==0||sts(fl.sent).length) bad.push('netHubTick with the party off still sends');
       netReset();

       // TWO: THE HOST. Two friends let in through the real hello handler; the one on seat 1 has his fast channel open.
       netStartHost();
       var f1=withFast(fake()), f2=fake(), f3=fake();
       NET.peers.push(f1); NET.peers.push(f2);
       var h1=netOnMsg(f1,js({t:'hello',proto:NET.proto,ver:VER,pid:'f1f1f1f1',name:'ZQX NEAR FRIEND'}));
       var h2=netOnMsg(f2,js({t:'hello',proto:NET.proto,ver:VER,pid:'f2f2f2f2',name:'ZQX FAR FRIEND'}));
       if(h1!=='welcome'||h2!=='welcome'||f1.seat!==1||f2.seat!==2){ bad.push('two stand-in friends were not let in as seats 1 and 2 (they heard '+h1+' and '+h2+')'); return stop(); }
       f1.sent=[]; f1.fs=[]; f2.sent=[];
       // Junk is refused, and so is a link that never said hello.
       var j1=netOnMsg(f1,js({t:'st',x:0,y:5,f:0}).replace(':0,',':1e999,')), j2=netOnMsg(f1,js({t:'st',x:'300',y:200,f:0}));
       NET.peers.push(f3);
       var j3=netOnMsg(f3,js({t:'st',x:100,y:100,f:0}));
       if(j1==='state'||j2==='state') bad.push('a position that is not a number was filed (the handler said '+j1+' and '+j2+')');
       if(j3==='state') bad.push('a link that never said hello had his position filed');
       for(i=0;i<NET.floor.length;i++) if(NET.floor[i]){ bad.push('a refused position left seat '+i+' on the floor'); break; }
       // The friend on seat 1 says where he stands, and claims seat 3.
       var s1=netOnMsg(f1,js({t:'st',s:3,x:300,y:200,f:0.5,m:0,r:0,lk:{fit:'moss',hair:'red',hat:'zqxnohat'}}));
       var g1=NET.floor[1]||null;
       if(s1!=='state'||!g1){ bad.push('the position of the friend on seat 1 was not filed (the handler said '+s1+')'); return stop(); }
       if(NET.floor[3]) bad.push('the host filed a friend under the seat he claimed, 3, not the seat of his link');
       if(!near1(g1,300,200)) bad.push('the first position from a friend did not put him where he said: '+xy(g1)+' for 300,200');
       if(!g1.lk||g1.lk.fit!=='moss'||g1.lk.hair!=='red'||g1.lk.hat!==undefined) bad.push('his look was not kept to rack ids: '+js(g1.lk));
       var r2=lastOf(sts(f2.sent));
       if(!r2||r2.s!==1||!near1(r2,300,200)) bad.push('the host did not pass the friend on seat 1 on to the friend on seat 2 ('+(f2.sent.join(' ')||'nothing sent')+')');
       else if(!r2.lk||r2.lk.fit!=='moss'||r2.lk.hat!==undefined) bad.push('the look passed on is not the cleaned one: '+js(r2.lk));
       if(sts(f1.sent).length||sts(f1.fs).length) bad.push('the host sent a friend his own position back');
       // A new spot eases him there rather than jumping.
       netOnMsg(f1,js({t:'st',x:340,y:230,f:1,m:1,r:0}));
       if(!near1(g1,300,200)) bad.push('a new position jumped the friend there at once: he is at '+xy(g1));
       netHubTick(1/60);
       if(!(g1.x>300.5&&g1.x<339.5&&g1.y>200.3&&g1.y<229.7)) bad.push('one floor tick after a new position the friend is at '+xy(g1)+', not part way from 300,200 to 340,230');
       // Where the host stands goes out while it ticks, and the friend arrives.
       HB.player.x=123.4; HB.player.y=234.5; HB.player.face=0.77; HB.player.moving=true; HB.player.rollT=0;
       f1.sent=[]; f1.fs=[]; f2.sent=[];
       for(i=0;i<60;i++) netHubTick(1/60);
       if(!near1(g1,340,230)) bad.push('a second after his new position the friend is drawn at '+xy(g1)+', not at 340,230');
       var q1=sts(f1.fs), q1r=sts(f1.sent), q2=sts(f2.sent), o1=lastOf(q1);
       if(!o1) bad.push('the host sent no position on the fast channel of the friend who has it open'+(q1r.length?' (it went on the reliable one)':''));
       else {
         if(o1.s!==0||Math.abs(o1.x-123.4)>0.05||Math.abs(o1.y-234.5)>0.05||Math.abs(o1.f-0.77)>0.01||o1.m!==1) bad.push('the host position reads '+js(o1)+', not seat 0 at 123.4,234.5 facing 0.77 and walking');
         if(q1.length<8||q1.length>11) bad.push('the host sent '+q1.length+' positions in a second of floor ticks, not about ten');
         if(!q1[0].lk||q1[0].lk.fit!==cosWorn('fit')||q1[0].lk.hair!==cosWorn('hair')) bad.push('the first position the host sent does not carry what he is wearing: '+js(q1[0].lk));
       }
       if(q1r.length) bad.push('the host put '+q1r.length+' positions on the reliable channel of a friend whose fast channel is open');
       if(!q2.length) bad.push('the host sent no position to the friend without a fast channel, where the reliable channel is the way');
       // THE FRAME. The friend is drawn once, as another body in his own fit and hair, where he stands, sorted with the player,
       // named over his head, and the rest of the frame is the solo frame operator for operator.
       home();
       frame();
       var m1=drawnAs(g1);
       if(m1.length!==1) bad.push('with the party on the floor drew the friend '+m1.length+' times, not once');
       else {
         if(m1[0].hero) bad.push('the friend was drawn as the player himself, not as another body');
         if(!near1(m1[0],340,230)) bad.push('the friend was drawn at '+xy(m1[0])+', not at 340,230 where he said he stands');
         if(m1[0].coat!==FITCOL.moss[1]||m1[0].hair!=='red') bad.push('the friend was not dressed from his own racks: coat '+m1[0].coat+' and hair '+m1[0].hair+' for moss and red');
         var hi=-1, gi=-1;
         for(i=0;i<ops.length;i++){ if(ops[i].hero&&hi<0) hi=i; if(ops[i].own===g1) gi=i; }
         if(hi>=0&&gi>=0&&Math.abs(keepP.y-230)>1&&((230>keepP.y)!==(gi>hi))) bad.push('the friend is not sorted into the floor with the player: standing '+((230>keepP.y)?'in front of':'behind')+' him he is drawn '+((gi>hi)?'after':'before')+' him');
       }
       if(sig(drawnBut(g1))!==soloSig) bad.push('with the party on the rest of the floor frame changed: '+drawnBut(g1).length+' other operators against '+soloN+' in the solo frame');
       if(!painted('ZQX NEAR FRIEND')) bad.push('the friend is drawn with no name over him');
       if(painted('ZQX FAR FRIEND')) bad.push('the friend who never said where he stands has his name painted on the floor');
       // THE UPDATE ticks the net floor code with the party on, and with the PARTY window open too, so a man reading the window
       // at the lift is still seen.
       calls.tick=0;
       updateHubWorld(1/60);
       var tk1=calls.tick;
       if(tk1!==1) bad.push('with the party on a floor update called netHubTick '+tk1+' times, not once');
       if(pm){
         pm.classList.add('on'); updateHubWorld(1/60); pm.classList.remove('on');
