       if(total(g.tel.kills)!==4) return 'SKIP: the raid record counted '+total(g.tel.kills)+' kills, not 4, here';
       g.ents.length=0; for(var ke=0;ke<keepEnts.length;ke++) g.ents.push(keepEnts[ke]);
