       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       g=__state(); if(!g||!g.player||g.sim||!g.zones||!g.zones.length||!g.tel) return 'SKIP: no live raid with an extraction point and a raid record';
       p=g.player;
