         if(said!==1) bad.push('the '+w.name+' ran dry with the trigger held and said Out of ammo '+said+' times over four held frames, not once');
       }
       letGo();
       // AND AGAIN: after letting go, a fresh pull on the empty gun clicks once more.
       clear(); hold(3);
       if(count('dry')!==1||outs()!==1) bad.push('after the held trigger ran the '+w.name+' dry and was let go, a fresh pull gave '+count('dry')+' dry clicks and '+outs()+' Out of ammo lines, not one of each');
     }catch(ex){ bad.push('threw: '+(ex&&ex.message||ex)); }
     finally{
       blip=_blip; say=_say;
       try{ mouse.down=false; for(var k2 in keys) keys[k2]=false; }catch(_m){}
       try{ if(g&&keepEnts) g.ents=keepEnts; if(g&&keep) g.hot=keepHot; }catch(_n){}
       try{ if(p&&keep){ for(var f2 in keep) p[f2]=keep[f2]; } }catch(_k){}
       try{ if(g&&!g.over) __endRaid('abandon'); }catch(_e){}
       try{ __topClear(); __resetCfg(); __cleanProfile(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'15.29',what:'a pillager going down sounds where he falls: one downed 60 units west of you is still heard close by on your left, and one downed 1400 units east of you plays the hit sound at his distance, out of earshot and on your right, or not at all, never the full volume centred hit you hear when you are hit (sound audit finding)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: this fixture cannot deploy';
     if(typeof updateEnts!=='function'||typeof blip!=='function'||typeof raiderDownHp!=='function') return 'SKIP: no entity update, blip or downed pillager in this build';
     if(typeof G!=='undefined'&&G&&G.sim) return 'SKIP: a sim is running';
     var bad=[], g=null, e=null, keepE=null, keepEnts=null, _blip=blip, hits=[], i;
     // A later control that cannot run keeps a failure already found, so the old build fails rather than skips.
     var skip=function(m){ return bad.length?(bad.join('; ')+' (then SKIP: '+m+')'):('SKIP: '+m); };
     // One entity update with only this pillager in the raid, at no health, dx units east of you (west when dx is negative).
     var down=function(dx){
       var p=g.player, hp0=p.hp;
       e.x=p.x+dx; e.y=p.y; e.hp=0; e.downed=0; e.finished=0; e.state='loot'; e.bag=[]; e.healQ=0; e.kitT=99;
       g.ents=[e]; hits.length=0;
       updateEnts(0.016);
       return {took:(e.downed===1&&e.state==='down'), hurt:(p.hp!==hp0)};
     };
     var side=function(h){ return 'distance '+h.d.toFixed(1)+' and pan '+h.pan.toFixed(3); };
     // What a hit sound with no distance or no pan is, in words; null when it carries both.
     var unplaced=function(h,where){
       if(typeof h.d!=='number') return 'a pillager downed '+where+' of you played the hit sound with no distance, at full volume'+(typeof h.pan!=='number'?' and centred':'')+', the same hit you hear when you are hit';
       if(typeof h.pan!=='number') return 'a pillager downed '+where+' of you played the hit sound at distance '+h.d.toFixed(1)+' with no pan, centred';
       return null;
     };
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       g=__state(); if(!g||!g.player||!g.ents) return 'SKIP: no live raid';
       if(g.sim) return 'SKIP: the raid is a sim, and a sim plays no sound';
       // CONTROL: pillagers go down rather than die here, so the downed branch is live.
       if(CFG.raiderDown===0) return 'SKIP: pillagers die outright here, so none goes down';
       for(i=0;i<g.ents.length&&!e;i++) if(g.ents[i].kind==='raider'&&!g.ents[i].downed&&!g.ents[i].finished&&!g.ents[i].merc) e=g.ents[i];
       if(e) keepE={x:e.x,y:e.y,hp:e.hp,downed:e.downed,downT:e.downT,finished:e.finished,state:e.state,alert:e.alert,goal:e.goal,cd:e.cd,bag:e.bag,healQ:e.healQ,kitT:e.kitT};
       else if(typeof mkRaider==='function'){ try{ e=mkRaider(g.player.x,g.player.y,null,true); }catch(_m){ e=null; } }
       if(!e) return 'SKIP: no pillager to put on the floor';
       keepEnts=g.ents;
       blip=function(t,d,pan){ if(String(t)==='hit') hits.push({d:d,pan:pan}); try{ return _blip.apply(null,arguments); }catch(_b){} };
       // NEAR: 60 units west. CONTROL: he went down on that update, you took nothing, and the recorder heard exactly one hit
       // sound, on either build, so a man downed beside you is heard and this recorder hears it.
       var near=down(-60);
       if(!near.took) return skip('a pillager at no health 60 units west did not go down on one entity update here (downed '+e.downed+', state '+e.state+')');
       if(near.hurt) return skip('you lost health on the entity update, so the hit sound cannot be told from a hit on you here');
       if(hits.length!==1) return skip('the recorder heard '+hits.length+' hit sounds when a pillager went down 60 units west, not one, so it cannot hear this sound here');
       var hn=hits[0];
       // THE FIX, NEAR: still heard close by, on his side.
       var un=unplaced(hn,'60 units west');
       if(un) bad.push(un+', not close by on your left');
       else if(!(hn.d>=59&&hn.d<=150&&hn.pan<0)) bad.push('a pillager downed 60 units west of you played the hit sound at '+side(hn)+', not close by on your left');
       // FAR: 1400 units east, well past where blip fades to nothing (about 880).
       var far=down(1400);
       if(!far.took) return skip('a pillager at no health 1400 units east did not go down on one entity update here (downed '+e.downed+', state '+e.state+')');
       if(far.hurt) return skip('you lost health on the second entity update, so the hit sound cannot be told from a hit on you here');
       // THE FIX, FAR: no hit sound at all, or one at his distance, out of earshot, on your right.
       if(hits.length>1) bad.push('a pillager downed 1400 units east of you played the hit sound '+hits.length+' times');
       else if(hits.length===1){
         var hf=hits[0], uf=unplaced(hf,'1400 units east');
         if(uf) bad.push(uf+', with nothing on screen and no health lost');
         else if(!(hf.d>=882&&hf.pan>0)) bad.push('a pillager downed 1400 units east of you played the hit sound at '+side(hf)+', not out of earshot on your right');
       }
     }catch(ex){ bad.push('threw: '+(ex&&ex.message||ex)); }
     finally{
       blip=_blip;
       try{ if(g&&keepEnts) g.ents=keepEnts; }catch(_n){}
       try{ if(e&&keepE){ e.x=keepE.x; e.y=keepE.y; e.hp=keepE.hp; e.downed=keepE.downed; e.downT=keepE.downT; e.finished=keepE.finished; e.state=keepE.state; e.alert=keepE.alert; e.goal=keepE.goal; e.cd=keepE.cd; e.bag=keepE.bag; e.healQ=keepE.healQ; e.kitT=keepE.kitT; } }catch(_k){}
       try{ if(g&&!g.over) __endRaid('abandon'); }catch(_e){}
       try{ __topClear(); __resetCfg(); __cleanProfile(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'15.28',what:'a grenade a pillager throws sounds where it lands: the Frag Charge he puts beside you plays the rising charge warning at the charge itself, the clank still plays at his hand, and the two scatter draws still land the charge where they always did (sound audit finding)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: this fixture cannot deploy';
     if(typeof raiderThrow!=='function'||typeof sfx!=='function'||typeof rr!=='function'||typeof rnd!=='function') return 'SKIP: no pillager throw, sfx or seeded draw in this build';
     if(!ITEMS.frag||ITEMS.frag.use!=='throw'||ITEMS.frag.tk!=='frag') return 'SKIP: no Frag Charge a pillager can throw in this build';
     if(typeof G!=='undefined'&&G&&G.sim) return 'SKIP: a sim is running';
     var bad=[], g=null, e=null, keepE=null, fr=null, _sfx=sfx, _rr=rr, heard=[], draws=0, i;
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       g=__state(); if(!g||!g.player||!g.frags) return 'SKIP: no live raid';
       if(g.sim) return 'SKIP: the raid is a sim, and a sim plays no sound';
       if(CFG.raiderKit===0) return 'SKIP: pillager kits are off here, so no pillager throws';
       var p=g.player;
       for(i=0;i<g.ents.length&&!e;i++) if(g.ents[i].kind==='raider'&&!g.ents[i].downed&&!g.ents[i].finished&&!g.ents[i].merc) e=g.ents[i];
       if(!e) return 'SKIP: no pillager to hand a charge to';
       keepE={x:e.x,y:e.y,bag:e.bag,thrT:e.thrT,smkT:e.smkT,hp:e.hp,rng:e.rng,kitThrows:e.kitThrows};
       var fR=(CFG.fragR===undefined?190:CFG.fragR), fd=fR+52+100;
       if(fd>=520) return 'SKIP: a blast radius of '+fR+' leaves no distance a pillager throws from';
       // Distinctive: he stands fd units east of you, a long-armed healthy man with one charge, and the two scatter draws are
       // pinned to 0.125 then 0.875, so his charge lands 19.5 west and 19.5 south of you: 27.6 from where you stand, and a
       // swapped draw order would put it 19.5 east instead.
       e.x=p.x+fd; e.y=p.y; e.bag=['frag']; e.thrT=0; e.smkT=99; e.hp=e.maxhp||100; e.rng=520;
       var DR=[0.125,0.875];
       rr=function(){ var v=(draws<DR.length)?DR[draws]:0.5; draws++; return v; };
       sfx=function(t,x,y){ heard.push({t:String(t),x:x,y:y}); };
       var n0=g.frags.length, threw=false;
       try{ threw=raiderThrow(e,p,fd,0.016); } finally { rr=_rr; sfx=_sfx; }
       fr=(g.frags.length>n0)?g.frags[g.frags.length-1]:null;
       // CONTROL: he threw one live charge of his own from inside his band, so a throw really happened.
       if(!threw||g.frags.length!==n0+1||!fr) return 'SKIP: the pillager would not throw from '+fd+' units here';
       if(fr.by!==e||!(fr.fuse>0)||fr.t!==0) return 'SKIP: the new charge is not his live charge here';
       // CONTROL: the pinned draws were taken, so where the charge lies is known.
       if(draws===0) return 'SKIP: the seeded draw stub did not take, so where the charge lands cannot be pinned';
       // CONTROL: the recorder heard the clank at his hand, so it hears the sounds a throw makes.
       var clank=heard.filter(function(h){ return h.t==='clank'&&Math.abs(h.x-e.x)<0.5&&Math.abs(h.y-e.y)<0.5; });
       if(!clank.length) return 'SKIP: the recorder heard no clank at the hand of the thrower ('+(heard.map(function(h){ return h.t; }).join(',')||'no sound')+'), so it cannot hear a throw here';
       // The scatter keeps its two draws in their old order.
       var wantX=p.x-19.5, wantY=p.y+19.5;
       if(draws!==2||Math.abs(fr.x-wantX)>0.001||Math.abs(fr.y-wantY)>0.001) bad.push('the charge took '+draws+' seeded draws and landed at '+(fr.x-p.x).toFixed(2)+','+(fr.y-p.y).toFixed(2)+' from you, not the two draws in order that put it at -19.50,19.50, so the seeded stream moved');
       // THE FIX: the warning plays at the charge itself.
       var dFr=Math.sqrt((fr.x-p.x)*(fr.x-p.x)+(fr.y-p.y)*(fr.y-p.y));
       var at=heard.filter(function(h){ return h.t==='charge'&&Math.abs(h.x-fr.x)<0.5&&Math.abs(h.y-fr.y)<0.5; });
       var off=heard.filter(function(h){ return h.t==='charge'&&!(Math.abs(h.x-fr.x)<0.5&&Math.abs(h.y-fr.y)<0.5); });
       if(!at.length){
         if(off.length) bad.push('the charge warning played '+Math.sqrt((off[0].x-fr.x)*(off[0].x-fr.x)+(off[0].y-fr.y)*(off[0].y-fr.y)).toFixed(1)+' units from where the charge lies, not at the charge');
         else bad.push('a charge a pillager threw landed '+dFr.toFixed(1)+' units from you with a '+fr.fuse+' second fuse and made no sound where it landed; the only sound was '+heard.map(function(h){ return h.t+' '+Math.round(Math.sqrt((h.x-p.x)*(h.x-p.x)+(h.y-p.y)*(h.y-p.y)))+' units away'; }).join(', '));
       }
     }catch(ex){ bad.push('threw: '+(ex&&ex.message||ex)); }
     finally{
       rr=_rr; sfx=_sfx;
       try{ if(g&&g.frags&&fr){ var fi=g.frags.indexOf(fr); if(fi>=0) g.frags.splice(fi,1); } }catch(_f){}
       try{ if(e&&keepE){ e.x=keepE.x; e.y=keepE.y; e.bag=keepE.bag; e.thrT=keepE.thrT; e.smkT=keepE.smkT; e.hp=keepE.hp; e.rng=keepE.rng; e.kitThrows=keepE.kitThrows; } }catch(_k){}
       try{ if(g&&!g.over) __endRaid('abandon'); }catch(_e){}
       try{ __topClear(); __resetCfg(); __cleanProfile(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'15.27',what:'the what is new card is current again: its version is within fifteen builds of the build and it names the healing news of v15.23 and v15.26, still opening with the alpha line',
   run:function(){
     if(!window.__words||typeof __words.whatsnew!=='function') return 'SKIP: this build cannot report its card';
     var wn=__words.whatsnew(), bad=[], L=wn.lines||[];
     var vNow=parseFloat(String(wn.build||'0').replace(/[^0-9.]/g,''))||0;
     var vCard=parseFloat(String(wn.ver||'0').replace(/[^0-9.]/g,''))||0;
     if(!(vNow&&vCard)) return 'SKIP: no version on the card or the build';
     if(this&&this.v&&vCard>parseFloat(this.v)+0.001) return 'SKIP: the card has moved on to v'+wn.ver+', a later card check covers it';
     if(vNow-vCard>0.15) bad.push('the card is at v'+wn.ver+' against a build at v'+wn.build+', more than fifteen builds behind');
     var all=L.join(' ').toUpperCase();
     var NEWS=['only a medkit','takes you past 85'].join(' ').toUpperCase();
     if(all.indexOf(NEWS)<0) bad.push('the card does not mention the healing news of v15.23 and v15.26');
     if(L[0]&&String(L[0]).toUpperCase().indexOf('ALPHA')<0) bad.push('the card no longer opens with what an alpha is');
     return bad.length?bad.join('; '):null; }},
  {v:'15.26',what:'a Bandage put on while a Medkit is still healing does not ride the Medkit up to 100: from 30, a Medkit and then a Bandage with about 6 of the Medkit left end no higher than 85 plus those 6, while three Bandages from 50 still stop at 85, a Medkit from 60 and a Bandage then a Medkit from 70 still reach 100, and with the heal ceilings off the two stack past it again (his ruling of 2026-09-16)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: this fixture cannot deploy';
     if(typeof applyHeal!=='function'||typeof tickHeal!=='function'||typeof healCeil!=='function'||typeof healAmt!=='function'||!ITEMS.bandage||!ITEMS.medkit) return 'SKIP: no heal over time or heal ceiling in this build';
     var bad=[], g=null, p=null, keep=null, keepBag=null, keepCaps=CFG.healCaps;
     // A later control that cannot run keeps a failure already found, so the old build fails rather than skips.
     var skip=function(m){ return bad.length?(bad.join('; ')+' (then SKIP: '+m+')'):('SKIP: '+m); };
     function fresh(hp){ p.hp=hp; p.healQ=0; p.healRate=0; p.healCap=undefined; p.healHi=0; p.healLo=undefined; p.prep=null; }
     function drain(left){ for(var i=0;i<4000&&p.healQ>left;i++) tickHeal(0.05); return p.hp; }
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       g=__state(); if(!g||!g.player) return 'SKIP: no live raid';
       p=g.player;
       keep={hp:p.hp,healQ:p.healQ,healRate:p.healRate,healCap:p.healCap,healHi:p.healHi,healLo:p.healLo,combatT:p.combatT,prep:p.prep};
       keepBag=(g.bag||[]).slice();
       var top=p.maxhp, lo=healCeil(ITEMS.bandage), aB=healAmt(ITEMS.bandage), aM=healAmt(ITEMS.medkit);
       // CONTROL: full health is 100, a Bandage stops at 85, and the items heal enough for every case below to reach its ceiling.
       if(top!==100||lo!==85) return 'SKIP: full health is '+top+' and the Bandage ceiling '+lo+' here';
       if(!(aB>=15&&aM>=40)) return 'SKIP: a Bandage heals '+aB+' and a Medkit '+aM+' here';
       // CONTROL A: three Bandages at once from 50 stop at 85, so the Bandage ceiling works at all.
       fresh(50); applyHeal('bandage'); applyHeal('bandage'); applyHeal('bandage');
       if(!(p.healQ>0)) return 'SKIP: a Bandage healed at once rather than over time here';
       var a=drain(0);
       if(a>lo+0.01) return 'SKIP: three Bandages from 50 reached '+a+', so the Bandage ceiling does not hold here';
       if(a<lo-0.01) bad.push('three Bandages from 50 stopped at '+a+', short of '+lo);
       // CONTROL B: a Medkit alone from 60 still reaches 100.
       fresh(60); applyHeal('medkit');
       var b=drain(0);
       if(b<top-0.01) bad.push('a Medkit from 60 stopped at '+b+', short of '+top);
       // THE FIX: a Medkit from 30 with about 6 left, then a Bandage. The Bandage may take him to 85 and the Medkit on by what it had left.
       fresh(30); applyHeal('medkit'); drain(6);
       var r=p.healQ;
       if(!(r>5&&r<=6&&p.hp<lo-5)) return skip('the Medkit from 30 did not leave about 6 below 85 here (left '+r+' at '+p.hp+')');
       applyHeal('bandage');
       var f=drain(0);
       if(f>lo+r+0.01) bad.push('from 30, a Bandage put on with '+r.toFixed(2)+' of a Medkit left ended at '+f.toFixed(2)+', past the '+(lo+r).toFixed(2)+' of 85 plus what the Medkit had left');
       if(f<lo+r-0.01) bad.push('from 30, a Bandage put on with '+r.toFixed(2)+' of a Medkit left stopped at '+f.toFixed(2)+', short of '+(lo+r).toFixed(2));
       // A Bandage from 70, part spent, then a Medkit: the Medkit still takes him to 100.
       fresh(70); applyHeal('bandage'); drain(10); applyHeal('medkit');
       var d=drain(0);
       if(d<top-0.01) bad.push('a Bandage from 70 and then a Medkit stopped at '+d.toFixed(2)+', short of '+top);
       // With the heal ceilings off, the same Medkit then Bandage stacks past 85 plus the Medkit left, as it always did.
       CFG.healCaps=0;
       fresh(30); applyHeal('medkit'); drain(6);
       var r2=p.healQ;
       applyHeal('bandage');
       var e=drain(0);
       if(!(e>lo+r2+0.01)) bad.push('with the heal ceilings off, a Medkit from 30 and then a Bandage stopped at '+e.toFixed(2)+', not past '+(lo+r2).toFixed(2));
     }catch(ex){ bad.push('threw: '+(ex&&ex.message||ex)); }
     finally{
       CFG.healCaps=keepCaps;
       try{ if(p&&keep){ p.hp=keep.hp; p.healQ=keep.healQ; p.healRate=keep.healRate; p.healCap=keep.healCap; p.healHi=keep.healHi; p.healLo=keep.healLo; p.combatT=keep.combatT; p.prep=keep.prep; } }catch(_k){}
       try{ if(g&&keepBag) g.bag=keepBag; }catch(_b){}
       try{ if(g&&!g.over) __endRaid('abandon'); }catch(_e){}
       try{ __topClear(); __resetCfg(); __cleanProfile(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'15.25',what:'belt key 1 never goes black while he holds a gun: the SMG taken from the backpack on key 3 over a pistol leaves cell 1 showing the SMG, the same key with one gun carried leaves cell 2 showing it, and a stowed carbine on key 5 shows on cell 2 while key 5 and key 2 each bring it up and keep the highlight on the key pressed (his note)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: this fixture cannot deploy';
     if(typeof hotbarSlots!=='function'||typeof equipFromBag!=='function'||typeof setHot!=='function'||typeof hotSel!=='function') return 'SKIP: no tactical belt or equip from the backpack in this build';
     if(!ITEMS.gun_smg||!ITEMS.gun_carbine||!WEAPONS.pistol||!WEAPONS.smg||!WEAPONS.carbine||!WEAPONS.fists) return 'SKIP: no pistol, SMG or carbine in this build';
     var bad=[], g=null, p=null, sl;
     function copyW(id){ var w={},k; for(k in WEAPONS[id]) w[k]=WEAPONS[id][k]; return w; }
     // The pistol in his hands; the carbine stowed, or bare hands in the second slot.
     function hands(two){
       p.downed=false; p.dying=false; p.roll=0; g.paused=false;
       p.wep=copyW('pistol'); p.ammo=p.wep.mag; p.wepIssued=false; p.wepFromArmory=false; p.reloading=0;
       if(two){ p.sec=copyW('carbine'); p.secAmmo=p.sec.mag; p.secIssued=false; p.secFromArmory=false; }
       else { p.sec=WEAPONS.fists; p.secAmmo=0; p.secIssued=true; p.secFromArmory=false; }
       p.swapped=false; g.hotAuto={}; G.hot=0;
     }
     function cell(i){ return sl[i]?(sl[i].kind+' '+sl[i].icon):'none'; }
     // A later control that cannot run keeps a failure already found, so the old build fails rather than skips.
     var skip=function(m){ return bad.length?(bad.join('; ')+' (then SKIP: '+m+')'):('SKIP: '+m); };
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       g=__state(); if(!g||!g.player) return 'SKIP: no live raid';
       p=g.player;
       // ONE, HIS NOTE: two guns carried, the SMG in the backpack on key 3, taken the way the key takes it.
       hands(true); g.bag=['gun_smg']; g.hotAssign={2:'gun_smg'};
       sl=hotbarSlots();
       // CONTROL: cell 1 is the pistol in his hands and key 3 is the SMG in the backpack.
       if(!(sl[0]&&sl[0].kind==='gun'&&sl[0].icon==='pistol')) return skip('cell 1 is not the pistol in his hands here ('+cell(0)+')');
       if(!(sl[2]&&sl[2].assigned&&sl[2].itemKey==='gun_smg'&&!sl[2].equipped)) return skip('key 3 is not the SMG in the backpack here ('+cell(2)+')');
       equipFromBag(g.bag.indexOf('gun_smg'),0);
       // CONTROL: the SMG is in his hands in place of the pistol, and key 3 shows it there.
       if(!(p.wep&&p.wep.id==='smg')) return skip('the SMG did not come up in his hands here (holding '+(p.wep&&p.wep.id)+')');
       sl=hotbarSlots();
       if(!(sl[2]&&sl[2].equipped&&sl[2].icon==='smg')) return skip('key 3 does not show the SMG in his hands here ('+cell(2)+')');
       if(!(sl[0]&&sl[0].kind==='gun'&&sl[0].icon==='smg')) bad.push('with the SMG taken from the backpack by key 3, cell 1 is '+cell(0)+' while he holds the SMG');
       // TWO: one gun carried, and key 3 pressed. The SMG goes to the empty second slot and comes up.
       hands(false); g.bag=['gun_smg']; g.hotAssign={2:'gun_smg'};
       setHot(2);
       // CONTROL: the SMG is in his hands and the pistol is stowed.
