     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       blip=_blip; say=_say; AC=_AC;
       try{ BUS=_BUS; }catch(_b2){}
       try{ REV=_REV; }catch(_r2){}
       try{ lastTs=keepTs; }catch(_t){}
       try{ if(g&&!g.over){ if(g.raidLen>0) g.timeLeft=g.raidLen; __endRaid('abandon'); } }catch(_e){}
       try{ __topClear(); __resetCfg(); __cleanProfile(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'15.23',what:'only a Medkit gets him back to 100: out of combat, regen from 80 stops at 85 with the heal ceilings on, and runs to 100 with them off (his ruling of 2026-09-16)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: this fixture cannot deploy';
