     if(!ROW||ROW.opts.length!==2||ROW.opts[0].cfg.superhot!==0||ROW.opts[1].cfg.superhot!==1) return 'SKIP: this build has no two-word Superhot row';
     var OFF=ROW.opts[0].n, ON=ROW.opts[1].n;
