     function rounds(g){ var p=g.player, S=(p.ammo||0)+(p.secAmmo||0)+(p.reserve||0), m=g.stowAmmo||{}, k, i; for(k in m) for(i=0;i<m[k].length;i++) S+=(m[k][i]|0); return S; }
     try{
