       var p=g.player;
       g.ents.length=0; g.waveT=-1e9;   // r1334c: an emptied raid is the urgent-wave condition
       p.downed=false; p.roll=0; p.ads=false; p.autoJog=false; p.stam=100; p.stamLock=0; p.stamRelease=0;
       clearKeys(); g.crouchTog=false;
