       try{ G=null; keys={}; showScreen('hub'); }catch(_q){}
       try{ __topClear(); __resetCfg(); __cleanProfile(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.22',what:'the what-is-new card names what changed how you play since v13.10, high enough to be drawn: B backs out of menus and a found armour plate goes to the backpack; the stamp is not older than what it lists; and no entry still claims the X key is gone',
   run:function(){
     if(typeof WHATSNEW==='undefined'||typeof WHATSNEW_VER==='undefined') return 'SKIP: this build has no what-is-new card';
     var bad=[];
     var ver=parseFloat(WHATSNEW_VER);
     if(!(ver>=13.16))
       bad.push('the card still says NEW IN v'+WHATSNEW_VER+', so a player coming back is told nothing about B backing out of menus or a found armour plate going to the backpack, both of which change how he plays');
     var idxB=-1, idxP=-1, idxX=-1, stale=false;
     for(var i=0;i<WHATSNEW.length;i++){
       var t=String(WHATSNEW[i]);
       if(idxB<0&&t.indexOf('TAB PAUSES AND BACKS OUT')===0) idxB=i;   // v13.45: B backed out until his TAB ruling
       if(idxP<0&&t.indexOf('AN ARMOUR PLATE YOU FIND')===0) idxP=i;
       if(idxX<0&&t.indexOf('X SEARCHES WHAT YOU ARE STANDING ON')===0) idxX=i;
       if(t.indexOf('key is gone')>=0) stale=true;
     }
     if(idxB<0)
       bad.push('the card never tells a player that B backs out of menus, which is the key he was given because Escape is not working for him, and a key nobody is told about does not exist');
     // r1342: no slot bound. Since v13.41 the top slots belong to the newest rulings.
     if(idxP<0)
       bad.push('the card never says a found armour plate now goes to the backpack, so the first plate he loots looks like it vanished');

     if(idxX<0)
       bad.push('the card never says X searches what you stand on, so the key for a body on the extraction point is one nobody is told about');
     if(stale)
       bad.push('an entry still says the X key is gone, while X is the search key, so the card contradicts the controls it describes');
     return bad.length?bad.join('; '):null; }},
  {v:'13.21',what:'the Recorder Copy button, where a failed Copy report sends the player, says whether the copy worked: Copied when it did, and when every copy route is refused it keeps the report selected and says press Ctrl+C (the only feedback path on itch)',
   run:function(){
     var btn=document.getElementById('copybtn'), ta=document.getElementById('exporttext');
     if(!btn||!ta||typeof btn.onclick!=='function') return 'SKIP: this fixture has no Recorder copy button to press';
     var desc; try{ desc=Object.getOwnPropertyDescriptor(navigator,'clipboard'); }catch(_d){ desc=null; }
     var redefined=false;
     try{ Object.defineProperty(navigator,'clipboard',{value:undefined,configurable:true}); redefined=(navigator.clipboard===undefined); }catch(_x){}
     if(!redefined) return 'SKIP: navigator.clipboard cannot be hidden here, so the button cannot be pressed synchronously';
     var bad=[], origExec=document.execCommand, was=btn.textContent, oldVal=ta.value;
     try{
       ta.value='PILLAGERS REPORT ZQX 5521';

       // ONE: refused everywhere. It must say so, and must say how to get it out.
       document.execCommand=function(){ return false; };
       btn.textContent=was;
       btn.onclick();
       var t1=String(btn.textContent||'');
       if(t1===was)
         bad.push('a refused copy leaves the Recorder button exactly as it was, so the place a failed Copy report sends the player cannot tell him the copy failed either, and on itch that is the last way his run reaches Daniel');
       if(t1.indexOf('Copied')>=0)
         bad.push('a copy refused on every route announces Copied, so he pastes an empty clipboard to Daniel and believes he sent a report');
       if(t1===was||t1.indexOf('Ctrl+C')<0)
         bad.push('when every copy route is refused he is not told the one thing that always works, that the report is selected and Ctrl+C copies it');

       // TWO: accepted. It must say so.
       document.execCommand=function(){ return true; };
       btn.textContent=was;
       btn.onclick();
       var t2=String(btn.textContent||'');
       if(t2.indexOf('Copied')<0)
         bad.push('a copy that worked says nothing, so he cannot tell a working button from a blocked one');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ document.execCommand=origExec; }catch(_r1){}
       try{ if(desc) Object.defineProperty(navigator,'clipboard',desc); else delete navigator.clipboard; }catch(_r2){}
       try{ btn.textContent=was; ta.value=oldVal; }catch(_r3){}
       try{ __topClear(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.20',what:'a run report does not claim to have been saved on a page that cannot save files: embedded says so and points at Copy report, and a normal page still downloads (the game is hosted in an itch iframe, which has no allow-downloads)',
   run:function(){
     // THE REAL ONE, kept by the fixture before it stubbed the name. Calling the
     // stub would measure the fixture, which is what the first version of this
     // check did.
     var dl=window.__realDownloadExport;
     if(typeof dl!=='function') return 'SKIP: this fixture did not keep the real report saver';
     if(typeof reportEmbedded!=='function')
       return 'this build cannot tell whether it is running inside somebody else page, so on itch it claims every run report was saved to a file while the frame silently refuses the download and the whole feedback path is lost without a word';
     var bad=[];
     var _re=reportEmbedded, _last=P.lastReport, clicks=0;
     var _ac=HTMLAnchorElement.prototype.click;
     try{
       // COUNT REAL DOWNLOAD ATTEMPTS. The string the old code set is exactly
       // what could not be trusted, so it is not what this leans on.
       // COUNT IT AND SWALLOW IT. Calling through would save a file into his
       // Downloads on every corpus run, which is what the fixture stub exists to
       // prevent in the first place.
       HTMLAnchorElement.prototype.click=function(){
         if(this.hasAttribute('download')){ clicks++; return; }
         return _ac.apply(this,arguments);
       };

       // ARM ONE: inside somebody else page.
       reportEmbedded=function(){ return true; };
       P.lastReport=null; clicks=0;
       dl();
       if(clicks>0)
         bad.push('the game still tries to download the report from inside an embedded page, where the click does nothing and throws nothing, so the run is thrown away');
       if(P.lastReport==='downloaded')
         bad.push('the game records the report as downloaded from a page that cannot save files, so every friend playing on itch is told their run was saved when it was not, and that is the entire feedback path today');
       if(!P.lastReport)
         bad.push('an embedded save records nothing at all, so there is no way to tell afterwards that the report never left');

       // ARM TWO: a normal page must still save, or the fix has taken the
       // feedback path away from the one place it actually works.
       reportEmbedded=function(){ return false; };
       P.lastReport=null; clicks=0;
       dl();
       if(clicks===0)
         bad.push('a normal page no longer saves the report to a file at all, so the fix removed the feedback path instead of repairing it');
       if(P.lastReport!=='downloaded')
         bad.push('a normal page saves the report and does not record it, so nothing downstream can tell the run was handed over');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ HTMLAnchorElement.prototype.click=_ac; }catch(_a){}
       try{ reportEmbedded=_re; }catch(_r){}
       try{ P.lastReport=_last; }catch(_l){}
       try{ __topClear(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.19',what:'a roll refused for stamina says so out loud instead of reading as a dead key, a roll that can happen stays silent, and holding the key does not repeat the line (his report of 2026-09-12)',
   run:function(){
     if(typeof tryRoll!=='function') return 'SKIP: this fixture cannot reach the roll';
     if(!(window.__deploy&&window.__state&&window.__loop&&window.__endRaid))
       return 'SKIP: this fixture cannot drive a live raid';
     var bad=[];
     var _say=say, heard=[];
     var T0=performance.now();
     function frames(k){ for(var f=0;f<(k||6);f++){ T0+=16.7; var st=__state(); if(!st||st.over) return; __loop(T0); } }
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       var g=__state();
       if(!g||!g.player) return 'SKIP: no raid to roll in';
       say=function(m){ heard.push(String(m)); try{ return _say.apply(null,arguments); }catch(_s){} };
       var p=g.player;
       p.downed=false; p.roll=0; p.rollCd=0;
       frames(2);

       // ONE: no legs. The refusal must speak.
       p.stam=1; g.rollSayT=0;
       heard.length=0;
       tryRoll();
       if(heard.length===0)
         bad.push('a roll refused because there is no stamina left says nothing at all, so a key that is working reads as a key that is broken, which is exactly the report he sent and then withdrew');
       if(__state().player.roll>0)
         bad.push('a roll happened on an empty stamina bar, so the cost is not being paid');

       // TWO, THE ARM WITH TEETH: a roll that CAN happen must stay silent.
       var p2=__state().player;
       p2.roll=0; p2.rollCd=0; p2.stam=100; __state().rollSayT=0;
       heard.length=0;
       tryRoll();
       if(!(__state().player.roll>0))
         bad.push('a full stamina bar cannot roll, so the roll is broken rather than merely quiet');
       if(heard.length>0)
         bad.push('a roll that actually happened announces itself as refused, so the line is wallpaper rather than an explanation');

       // THREE: holding the key must not repeat it. Space is held.
       var p3=__state().player;
       p3.roll=0; p3.rollCd=0; p3.stam=1; __state().rollSayT=0;
       heard.length=0;
