     var bad=[], P2=__P();
     var KEEP={}, F=['pname','credits','xp','xpLevel','runs','ext','died','best','notoriety',
                     'pack','racks','arrays','cstand','netEarn','mapIx','cond','wxPick','stash','weapons','equipped'], fi;
     for(fi=0;fi<F.length;fi++) KEEP[F[fi]]=P2[F[fi]];
