       P2.pname='MAKER'; P2.credits=123457; P2.xp=8801; P2.xpLevel=7;
       P2.runs=77; P2.ext=41; P2.died=19; P2.best=52111; P2.notoriety=3;
       P2.pack=2; P2.racks=5; P2.arrays=1; P2.cstand=4;
       P2.netEarn=771122; P2.mapIx=1; P2.cond='night'; P2.wxPick='any';
       var code=restoreMake();
       if(!code) return 'SKIP: no restore code could be made from a staged profile';
       // THE CHARACTER BEING REPLACED, carrying a different lifetime figure.
       P2.pname='RESTORER'; P2.credits=1; P2.xp=1; P2.xpLevel=1;
       P2.runs=4; P2.ext=1; P2.died=3; P2.best=900; P2.notoriety=0;
       P2.netEarn=404404;
       if(restoreApply(code)!==true) return 'SKIP: the restore refused a code this check had just made';
       if(P2.netEarn===404404)
         bad.push('the restored character wears the lifetime earnings of the player who restored it: the panel says the code REPLACES the save he is playing, and every other counter was replaced, so the career card now states somebody else figure as a fact about this character');
       else if(P2.netEarn!==771122)
         bad.push('the restored character lifetime earnings came back as '+P2.netEarn+' rather than the 771122 the code was made from');
       // CONTROL: EVERY COUNTER THE RESTORE ALREADY CARRIED still arrives. Adding a
       // field changes the object every code is built from.
       var want={pname:'MAKER',credits:123457,xp:8801,xpLevel:7,runs:77,ext:41,died:19,best:52111,notoriety:3,pack:2,racks:5,arrays:1,cstand:4};
       for(var k in want) if(P2[k]!==want[k])
         bad.push('control: the restore no longer carries '+k+': it arrived as '+P2[k]+' rather than '+want[k]+', so adding a field has dropped one that was already there');
       // A CODE MADE BEFORE THIS BUILD has no key for it, and must ZERO the field
       // rather than leave the previous character figure standing. These codes are
       // in the wild in his run reports.
       var old=restoreMake();
       try{ delete old.ne; }catch(_d){ old.ne=undefined; }
       P2.netEarn=404404;
       if(restoreApply(old)!==true) return 'SKIP: the restore refused a code with the new key removed';
       if(P2.netEarn===404404)
         bad.push('a restore code made before this build leaves the previous character lifetime earnings in place, which is the same wrong number under a different name');
       else if(P2.netEarn!==0)
         bad.push('a restore code with no lifetime figure in it set the field to '+P2.netEarn+' rather than an honest zero');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ for(var fj=0;fj<F.length;fj++) P2[F[fj]]=KEEP[F[fj]]; saveProfile(); }catch(_p){}
       try{ __topClear(); __cleanProfile(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.96',what:'the career card counts times he got back up and not pillagers he picked up: three pickups on a clean run read as none, a real stand-up still reads as one, a run with both counts only the stand-up, and the report he is sent carries the same number as the card (audit finding 12, 2026-09-11)',
   run:function(){
     if(typeof statSummary!=='function') return 'SKIP: this fixture cannot summarise the run log';
     if(!window.__P) return 'SKIP: this fixture cannot reach the profile';
     var bad=[], P2=__P(), keepLog=(P2.log||[]).slice();
     function run(o){
       return {n:o.n,outcome:'extract',ver:'1.00',preset:'std',weapon:'Fists',dur:30,haul:100,
               containers:1,shots:0,hits:0,heals:0,kills:{sentry:0,crawler:0,raider:0,snitch:0},
               downs:o.downs,revives:o.revives,raiderRevives:o.picked,tags:[],note:''};
     }
     try{
       // A CLEAN RUN WITH THREE PILLAGERS PICKED UP. He never went down.
       var clean=[run({n:1,downs:0,revives:3,picked:3})];
       var a=statSummary(clean);
       if(a.downs!==0)
         bad.push('control: the run planted as a clean one is summarised as '+a.downs+' downs, so this check is reading something other than the run it planted');
       if(a.revives!==0)
         bad.push('a raid he walked through without going down once says he got back up '+a.revives+' times, because reviving a downed pillager is counted as him standing up: the card prints Went down 0 with that number directly underneath it');
       // A REAL STAND-UP AND NOBODY PICKED UP. This is the control: a build that
       // simply printed zero would pass every other arm.
       var stood=[run({n:1,downs:1,revives:1,picked:0})];
       var b=statSummary(stood);
       if(b.revives!==1)
         bad.push('control: a raid where he went down and got back up once now says '+b.revives+', so the count has been zeroed rather than corrected');
       // BOTH IN ONE RAID: he stood up once and picked up one pillager.
       var both=[run({n:1,downs:1,revives:2,picked:1})];
       var c=statSummary(both);
       if(c.revives!==1)
         bad.push('a raid where he got back up once and picked up one pillager counts '+c.revives+' stand-ups rather than 1');
       // THE REPORT HE IS SENT MUST AGREE WITH THE CARD, or two documents describe
       // the same raid differently.
       if(typeof buildExport==='function'){
         P2.log=clean.slice();
         var rep=''; try{ rep=buildExport()||''; }catch(_x){}
         var m=/\brev:(\d+)/.exec(rep);
         if(!m) bad.push('control: the run report no longer carries a stand-up count at all, so the card and the report cannot be compared');
         else if(+m[1]!==0)
           bad.push('the report he sends says rev:'+m[1]+' for a raid he walked through without going down, so the file a friend copies out disagrees with the card on the same raid');
         P2.log=stood.slice();
         var rep2=''; try{ rep2=buildExport()||''; }catch(_y){}
         var m2=/\brev:(\d+)/.exec(rep2);
         if(m2&&+m2[1]!==1)
           bad.push('control: the report says rev:'+m2[1]+' for a raid where he really did get back up once');
       }
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ P2.log=keepLog; saveProfile(); }catch(_p){}
       try{ __topClear(); __cleanProfile(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.95',what:'the Undercroft pause box owns the keyboard: SPACE stores no roll, TAB and I do not open the backpack underneath it, H does not flip the controls panel and ENTER does not spend the unread update card, while P still closes the box and every one of those keys still works with the box down (audit finding 10, 2026-09-11, the floor twin of v12.22)',
   run:function(){
     if(!(window.__hubEnter&&window.__hub&&window.__hubP&&window.__keysRef&&window.__hubBag))
       return 'SKIP: this fixture cannot reach the Undercroft floor';
     if(typeof togglePauseBox!=='function') return 'SKIP: this build has no pause box to raise';
     var pb=document.getElementById('pausebox');
     if(!pb) return 'SKIP: this build has no pause box element';
     var bad=[];
     function tap(c){
       var K=__keysRef(); for(var k in K) K[k]=false;
       window.dispatchEvent(new KeyboardEvent('keydown',{code:c,key:c,bubbles:true,cancelable:true}));
       window.dispatchEvent(new KeyboardEvent('keyup',{code:c,key:c,bubbles:true,cancelable:true}));
     }
     function boxUp(){ return pb.classList.contains('on'); }
     try{
       __topClear(); __runPrep(); __resetCfg(); __cleanProfile();
       __hubEnter();
       var HBx=__hub();
       if(!HBx||!HBx.player) return 'SKIP: the floor has no walking character to test';
       // Each key: once with the box up, which must do nothing, and once with it
       // down, which must do the thing. The second half is the control.
       function paired(code,read,reset){
         reset();
         togglePauseBox(true);
         if(!boxUp()){ bad.push('control: the pause box would not open on the floor, so nothing here is being tested'); return; }
         tap(code);
         var whilePaused=read();
         togglePauseBox(false); pb.classList.remove('on');
         reset();
         tap(code);
         var whileFree=read();
         reset();
         return {paused:whilePaused,free:whileFree};
       }
       // SPACE: a roll stored behind the box is spent the instant he closes it, so
       // his character dodge-rolls out of nothing on resume.
       var r=paired('Space',function(){ return (__hubP()&&__hubP().rollT)||0; },
                    function(){ var q=__hubP(); if(q){ q.rollT=0; } });
       if(r){
         if(r.paused>0) bad.push('SPACE while the pause box is up stores a roll, and the floor is frozen so it is not spent until he closes the box: his character dodge-rolls out of nothing the moment the game resumes');
         if(!(r.free>0)) bad.push('control: with the box down SPACE no longer rolls at all, so the key has been taken away rather than held back');
       }
       // TAB and I: the backpack opens invisibly under a 90 percent overlay, so
       // closing the box reveals a backpack he never opened.
       var _bagKeys=['KeyI','KeyB'], bi;   // v13.45: B opens the backpack too; TAB pauses on the floor and v13.44 owns that press
       for(bi=0;bi<_bagKeys.length;bi++){
         var rb=paired(_bagKeys[bi],function(){ return !!__hubBag(); },function(){ __hubBag(false); });
         if(rb){
           if(rb.paused) bad.push('['+_bagKeys[bi]+'] while the pause box is up opens the backpack underneath it, so closing the box reveals a backpack he never saw open');
           if(!rb.free) bad.push('control: with the box down ['+_bagKeys[bi]+'] no longer opens the backpack');
         }
       }
       // H: the controls panel flips under the box.
       var rh=paired('KeyH',function(){ return !!(__hub()&&__hub().legend); },
                     function(){ var q=__hub(); if(q) q.legend=false; });
       if(rh){
         if(rh.paused) bad.push('H while the pause box is up flips the controls panel behind it');
         if(!rh.free) bad.push('control: with the box down H no longer shows the controls');
       }
       // ENTER: the unread update card behind the box is spent. Only a returning
       // player has one, because a profile with no runs has it stamped seen.
       if(typeof WNSEEN!=='undefined'){
         var re=paired('Enter',function(){ return !!WNSEEN; },function(){ WNSEEN=0; });
         if(re){
           if(re.paused) bad.push('ENTER while the pause box is up marks the update card read, and the card is behind the box, so he never sees what he has just thrown away');
           if(!re.free) bad.push('control: with the box down ENTER no longer dismisses the update card');
         }
         try{ WNSEEN=1; }catch(_w){}
       }
       // CONTROL: P STILL CLOSES THE BOX. A lockout that stopped its own two keys
       // would leave him unable to unpause.
       togglePauseBox(true);
       if(boxUp()){
         tap('KeyP');
         if(boxUp()) bad.push('control: with the box up P no longer closes it, so the lockout has taken the two keys the box itself names');
       }
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ if(pb.classList.contains('on')){ togglePauseBox(false); pb.classList.remove('on'); } }catch(_b){}
       try{ __hubBag(false); var q2=__hub(); if(q2){ q2.legend=false; if(q2.player) q2.player.rollT=0; } }catch(_h){}
       try{ var K2=__keysRef(); for(var k2 in K2) K2[k2]=false; }catch(_k){}
       try{ __topClear(); __resetCfg(); __cleanProfile(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.94',what:'going down inside a landed extraction shows the extract verb and blocks the surrender even when it is not the ring he called himself, while a single ring he did call behaves exactly as v12.81 left it and lying outside every ring still offers the surrender (audit finding 8, 2026-09-11)',
