            if(g2){ if(g2.zones) for(var z=0;z<g2.zones.length;z++){ g2.zones[z].beaconT=null; g2.zones[z].hold=null; g2.zones[z].holdMax=null; }
                    g2.active=null; g2.beaconT=null; g2.shipHold=null;
