       var onBelt=false; for(var bi in (g.hotAssign||{})) if(g.hotAssign[bi]==='gun_rifle') onBelt=true;
       if(!onBelt) bad.push('staging: autoBelt did not pin the bought rifle to a belt cell, so the line has no key to name');
       else if(!/tactical belt, key [1-9]/.test(m1)) bad.push('the rifle line said "'+m1+'" and not which belt key it went to');
       if(g.bag.indexOf('gun_rifle')<0) bad.push('control: the bought rifle is not in the bag');
       // THE MEDKIT WITH NO KEY SET: the backpack.
       g.msg=''; pedBuy(1);
       var m2=g.msg||'';
       if(!/In your backpack/.test(m2)) bad.push('a medkit bought with no key set said "'+m2+'" and not In your backpack');
       // THE MEDKIT ON KEY 6.
       g.hotAssign[5]='medkit'; g.msg=''; pedBuy(2);
       var m3=g.msg||'';
       if(!/tactical belt, key 6/.test(m3)) bad.push('a medkit bought with key 6 set to medkit said "'+m3+'" and not key 6');
       // THE PURCHASE ITSELF, unchanged: the credits fell by the three prices.
       if(P2.credits!==5000-60) bad.push('control: credits are '+P2.credits+' after three purchases priced 10, 20 and 30 from 5000');
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{
       // The raid ends FIRST: endRaid pays the credits out and re-sorts the two
       // gun slots, so anything put back before it runs is overwritten by it.
       try{ var g2=__state(); if(g2&&!g2.over){ g2.trade=null; g2.player.downed=false; __endRaid('abandon'); } }catch(_e){}
       P2.credits=keepC; P2.equippedSec=keepSec; P2.equipped=keepEq; P2.weapons=keepW;
       try{ saveProfile(); }catch(_s){}
       __topClear(); __cleanProfile();
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.27',what:'a stash drop onto the backpack for an item bound to a key with nothing packed lands on that key with a count and words, a bound key with nothing packed shows a 0 on the plan, and a spent belt key in a raid says No Bandage left (his note of 2026-09-07: bandages did not come over)',
   run:function(){
     if(!(window.__P&&window.__hubEnter&&window.__showScreen&&window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: this fixture cannot reach the stash screen and a raid';
     if(typeof renderHub!=='function'||typeof packedCount!=='function'||typeof useHot!=='function'||typeof hotbarSlots!=='function') return 'SKIP: this build has no belt plan to measure';
     var bad=[], P2=__P(), keep={stash:(P2.stash||[]).slice(),kit:(P2.kit||[]).slice(),hot:JSON.parse(JSON.stringify(P2.hotAssign||{})),freeKit:P2.freeKit};
     function zeroOn(cell){ var sp=cell.querySelectorAll('span'), i; for(i=0;i<sp.length;i++) if((sp[i].textContent||'').trim()==='0') return true; return false; }
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       try{ var g0=__state(); if(g0&&!g0.over){ g0.player.downed=false; __endRaid('abandon'); } }catch(_0){}
       keys={}; __showScreen('hub'); __hubEnter();
       // A key left on Bandage by the last raid (dropDeadKeys keeps it while the stash has one), nothing packed, three in the stash.
       P2.stash=['bandage','bandage','bandage','wire']; P2.kit=[]; P2.hotAssign={2:'bandage'}; P2.freeKit=0; saveProfile();
       renderHub();
       var hub=document.getElementById('hub'); if(hub) hub.classList.add('on');
       // (B) the plan cell for key 3 says 0.
       var cell=document.querySelector('#hub [data-plan="2"]');
       if(!cell) bad.push('staging: no plan cell for key 3 on the stash screen');
       else if(!zeroOn(cell)) bad.push('the plan cell for key 3, set to Bandage with none packed, shows no 0');
       // (A) the drop, through the real pointer dropzone handler.
       var col=document.getElementById('kitcol');
       if(!col||typeof col.__grabDrop!=='function') return 'SKIP: the backpack column takes no pointer drop';
       HUBSAY=''; col.__grabDrop('bandage','stash');
       var nb=packedCount('bandage'), kn=document.getElementById('kitn'), shown=kn?parseInt(kn.textContent,10):-1;
       if(nb<1) bad.push('the drop packed nothing');
       if(!(shown>0)) bad.push('after the drop the backpack column shows '+shown+' items: the Bandage vanished into the key');
       if(!/key 3/.test(HUBSAY||'')) bad.push('the drop said "'+(HUBSAY||'')+'" and not which key took it');
       var c2=document.querySelector('#hub [data-plan="2"]');
       if(c2&&nb>1&&(c2.textContent||'').indexOf('x'+nb)<0) bad.push('the plan cell does not show x'+nb+' after the drop (it reads "'+(c2.textContent||'').trim()+'")');
       // CONTROL: the same drop with no key bound packs one copy, as it always has.
       P2.kit=[]; P2.hotAssign={}; saveProfile(); renderHub(); col.__grabDrop('wire','stash');
       if(packedCount('wire')!==1) bad.push('control: a drop with no key bound packed '+packedCount('wire')+' copies, not one');
       if(hub) hub.classList.remove('on');
       // (C) in a raid, a key on a Bandage with none in the bag says so.
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       var g=__state();
       g.hotAssign={2:'bandage'}; g.hotAuto={}; g.bag=[]; g.msg=''; g.hot=2;
       var sl=hotbarSlots(), s2=sl[2];
       if(!(s2&&s2.assigned&&s2.itemKey==='bandage')) bad.push('staging: belt cell 3 is not the assigned Bandage cell (kind '+(s2&&s2.kind)+')');
       useHot();
       if(!/No Bandage left/.test(g.msg||'')) bad.push('a spent Bandage key said "'+(g.msg||'')+'", not No Bandage left');
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{
       try{ var g2=__state(); if(g2&&!g2.over){ g2.player.downed=false; __endRaid('abandon'); } }catch(_e){}
       P2.stash=keep.stash; P2.kit=keep.kit; P2.hotAssign=keep.hot; P2.freeKit=keep.freeKit;
       try{ saveProfile(); }catch(_s){}
       try{ var hb2=document.getElementById('hub'); if(hb2) hb2.classList.remove('on'); }catch(_h){}
       __topClear(); __cleanProfile();
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.26',what:'taking the freebie kit at the stash and then confirming FREEBIE KIT at the lift keeps the record of what he had packed, and a run that ends dead leaves that gear in his stash with an empty backpack and belt and a card that says so (his note of 2026-09-07 built it, his note of 2026-09-11 reversed what comes back)',
   run:function(){
     if(!(window.__startRaid&&window.__state&&window.__endRaid&&window.__P&&window.__hubEnter&&window.__showScreen)) return 'SKIP: this fixture cannot start a raid';
     if(typeof askKit!=='function'||typeof commitKit!=='function'||typeof renderFreeKit!=='function'||typeof ascendNow!=='function') return 'SKIP: this fixture cannot reach the lift question';
     var bad=[], P2=__P();
     var keep={stash:(P2.stash||[]).slice(),kit:(P2.kit||[]).slice(),hot:JSON.parse(JSON.stringify(P2.hotAssign||{})),freeKit:P2.freeKit,kitSaved:P2.kitSaved,kbf:P2.kitBeforeFree,chosen:P2.kitChosen,drop:(P2.dropKit||[]).slice(),weapons:(P2.weapons||[]).slice(),eq:P2.equipped,safe:P2.safe,gun:P2._gunSlot};
     var _asc=ascendNow, alt=null;
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       try{ var g0=__state(); if(g0&&!g0.over){ g0.player.downed=false; __endRaid('abandon'); } }catch(_0){}
       keys={}; __showScreen('hub'); __hubEnter();
       // DISTINCTIVE: three items no fallback packs together, one of them on a key.
       P2.stash=['smoke','decoy','wire','medkit','bandage']; P2.kit=['smoke','decoy','wire']; P2.hotAssign={3:'smoke'}; P2.safe=null;
       P2.freeKit=0; P2.kitSaved=null; P2.kitBeforeFree=null; P2.kitChosen=0; P2.weapons=['pistol']; P2.equipped='fists'; saveProfile();
       // STEP ONE: the stash button takes the freebie kit, for real.
       renderFreeKit(); var fb=document.querySelector('.fkbtn');
       if(!fb||!fb.onclick) return 'SKIP: the freebie kit button was not drawn';
       fb.onclick();
       if(!P2.freeKit) bad.push('staging: the stash button did not take the kit');
       if(!(P2.kitSaved&&P2.kitSaved.kit&&P2.kitSaved.kit.length===3)) bad.push('staging: the stash button did not keep the three items aside');
       // STEP TWO: the lift asks, and he answers FREEBIE KIT again.
       askKit(); alt=ASKALT;
       if(typeof alt!=='function') return 'SKIP: the lift question offers no FREEBIE KIT answer';
       ascendNow=function(){ commitKit(); };
       alt();
       ascendNow=_asc;
       // THE FINDING: on v12.25 the answer re-snapshotted the emptied kit, so nothing was kept.
       var kb=(P2.kitBeforeFree||[]).slice().sort().join(',');
       if(kb!=='decoy,smoke,wire') bad.push('after FREEBIE KIT at the lift the packing kept for the restore is ['+kb+'], not the three items packed at the stash');
       // THE RUN ENDS DEAD: the real restore path.
       __startRaid({mapIx:0,seed:4242});
       var g=__state();
       if(!g||!g.freeKit) bad.push('control: the raid did not take the free kit');
       if(g){ g.player.downed=false; __endRaid('dead'); }
       // v12.87, HIS NOTE 2026-09-11: the loadout does NOT come back. It stays in
       // the stash and he arrives with an empty backpack and belt. The record the
       // steps above protect is what the card is built from to tell him where his
       // gear went, so it matters more now rather than less.
       var kit=(P2.kit||[]).slice().sort().join(',');
       if(kit!=='') bad.push('after the death the backpack holds ['+kit+'] rather than nothing, so he reaches the Undercroft already packed');
       var _nk=0,_hk; for(_hk in (P2.hotAssign||{})) if(P2.hotAssign[_hk]) _nk++;
       if(_nk) bad.push('after the death '+_nk+' tactical belt key'+(_nk===1?'':'s')+' is still bound, so the belt he went up with came back down with him');
       var _in=0,_wn,_want=['smoke','decoy','wire'];
       for(_wn=0;_wn<_want.length;_wn++) if((P2.stash||[]).indexOf(_want[_wn])>=0) _in++;
       if(_in!==3) bad.push('the three items he had packed before the freebie kit are not in his stash after the death: '+_in+' of 3 are there');
       var txt=''; try{ txt=((document.getElementById('outcome')||{}).innerText||'').replace(/\s+/g,' '); }catch(_t){}
       if(txt.indexOf('KILLED IN ACTION')<0) bad.push('control: the card did not open on the death');
       if(txt.indexOf('in your stash')<0) bad.push('the card does not tell him where the gear he had packed before the freebie kit went');
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{
       ascendNow=_asc;
       try{ var g2=__state(); if(g2&&!g2.over){ g2.player.downed=false; __endRaid('extract'); } }catch(_e){}
       P2.stash=keep.stash; P2.kit=keep.kit; P2.hotAssign=keep.hot; P2.freeKit=keep.freeKit; P2.kitSaved=keep.kitSaved; P2.kitBeforeFree=keep.kbf; P2.kitChosen=keep.chosen; P2.dropKit=keep.drop; P2.weapons=keep.weapons; P2.equipped=keep.eq; P2.safe=keep.safe; P2._gunSlot=keep.gun;
       try{ saveProfile(); }catch(_s){} try{ renderFreeKit(); }catch(_rf){}
       try{ var am=document.getElementById('askmodal'); if(am) am.classList.remove('on'); }catch(_am){}
       __topClear(); __cleanProfile();
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.25',what:'the corner credits and XP readout and the floor answer line carry the window zoom: at 4K and 1440p they follow the monitor and the Text size setting like every window, and at 1080p the readout still clears the stash top row and the raid CONDITIONS box (his note of 2026-09-07)',
   run:function(){
     if(!(window.__forceSize&&window.__hubEnter&&window.__showScreen&&window.__P&&window.__deploy&&window.__frame&&window.__state&&window.__endRaid&&window.__pinDPR)) return 'SKIP: this fixture cannot resize and deploy';
     if(typeof applyMenuZoom!=='function'||typeof titleRes!=='function') return 'SKIP: no menu zoom in this build';
     var el=document.getElementById('topright'), toast=document.getElementById('hubtoast');
     if(!el||!toast) return 'SKIP: no corner readout or floor answer line in this build';
     if(!window.innerWidth||!window.innerHeight) return 'SKIP: the pane is 0x0, nothing here can be measured';
     var bad=[], P2=__P(), keepZ=P2.menuZoom, keepU=P2.uiScale, keepC=P2.credits, keepX=P2.xp;
     function rd(){ var r=el.getBoundingClientRect(); return {z:parseFloat(el.style.zoom)||1,h:r.height||0,w:r.width||0,l:r.left,r:r.right,b:r.bottom}; }
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile(); __pinDPR(1);
       try{ var g0=__state(); if(g0&&!g0.over) __endRaid('abandon'); }catch(_0){}
       keys={}; __showScreen('hub'); __hubEnter();
       P2.credits=1234567; P2.xp=12345; P2.menuZoom=1.3; delete P2.uiScale; saveProfile();   // distinctive and seven figures wide; saveProfile runs syncTopRight
       __forceSize(1920,1080); applyMenuZoom();
       var a=rd();
       if(!(a.h>0&&a.w>0)) return 'SKIP: the readout has no box at 1080p ('+a.w.toFixed(0)+'x'+a.h.toFixed(0)+')';
       // THE FINDING, 4K: on v12.24 el.style.zoom is empty, so the readout is the same 44 pixels at every size.
       __forceSize(3840,2160); applyMenuZoom();
       if(!(W>=3000)) return 'SKIP: the canvas would not go to 4K ('+W+'x'+H+')';
       var want=((typeof menuScale==='function')?menuScale():Math.max(1,P2.menuZoom)*titleRes()), c=rd();
       if(Math.abs(c.z-want)>0.05) bad.push('at 4K the readout zoom is '+c.z+' where the windows are at '+want.toFixed(2));
       if(!(c.h>a.h*1.4)) bad.push('at 4K the readout is '+c.h.toFixed(0)+'px tall against '+a.h.toFixed(0)+' at 1080p: it did not follow the monitor');
       var tz=parseFloat(toast.style.zoom)||1;
       if(Math.abs(tz-want)>0.05) bad.push('the floor answer line is at zoom '+tz+', not '+want.toFixed(2));
       // 1440p sits between the two.
       __forceSize(2560,1440); applyMenuZoom();
       var b=rd();
       if(!(b.h>a.h*1.2&&b.h<c.h)) bad.push('at 1440p the readout is '+b.h.toFixed(0)+'px tall, not between 1080p ('+a.h.toFixed(0)+') and 4K ('+c.h.toFixed(0)+')');
       // THE TEXT SIZE SETTING REACHES IT: the real Settings button, not the field.
       __forceSize(1920,1080); P2.menuZoom=1.3; delete P2.uiScale; applyMenuZoom();
       var h0=rd().h;
       if(typeof renderSettings==='function'&&document.getElementById('setlist')){
         renderSettings();
         var bt=document.getElementById('set_text');
         if(bt){ bt.click(); var h1=rd().h; if(!(Math.abs(h1-h0)>1)) bad.push('the Text size button did not move the readout, '+h0.toFixed(0)+' then '+h1.toFixed(0)); }
         else bad.push('staging: no Text size button in Settings');
       }
       P2.menuZoom=1.3; delete P2.uiScale; applyMenuZoom();
       // CONTROL ONE, 1080p: the readout is 1.3 times wider now and must still clear the stash top row (CLOSE).
       var hub=document.getElementById('hub');
       if(hub){ try{ renderHub(); }catch(_rh){} hub.classList.add('on'); }
       var r2=el.getBoundingClientRect(), tr=hub?hub.querySelector('.toprow'):null;
       if(tr){
         var bs=tr.querySelectorAll('button'), i;
         for(i=0;i<bs.length;i++){ var r1=bs[i].getBoundingClientRect(); if(r1.width>0&&r1.right>r2.left&&r1.left<r2.right&&r1.bottom>r2.top&&r1.top<r2.bottom) bad.push('control: at 1080p the readout ('+Math.round(r2.left)+'..'+Math.round(r2.right)+') covers the stash top row button "'+(bs[i].textContent||'').trim()+'" ('+Math.round(r1.left)+'..'+Math.round(r1.right)+')'); }
       } else bad.push('staging: no stash top row to measure against');
       if(hub) hub.classList.remove('on');
       // CONTROL TWO: a raid still starts CONDITIONS under the zoomed readout, the v11.78 rule.
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       __frame(0.016); __frame(0.016);
       var rb=el.getBoundingClientRect().bottom, C=(typeof HUDBOX!=='undefined')?HUDBOX.cond:null;
       if(!C) bad.push('control: the raid drew no CONDITIONS box');
       else if(C.y<rb-0.5) bad.push('control: the CONDITIONS box starts at '+C.y.toFixed(0)+', above the readout bottom at '+rb.toFixed(0));
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{
       P2.menuZoom=keepZ; if(keepU===undefined) delete P2.uiScale; else P2.uiScale=keepU; P2.credits=keepC; P2.xp=keepX;
       try{ saveProfile(); }catch(_s){}
       try{ var g2=__state(); if(g2&&!g2.over) __endRaid('abandon'); }catch(_e){}
       try{ var hb2=document.getElementById('hub'); if(hb2) hb2.classList.remove('on'); }catch(_h){}
       try{ __forceSize(1920,1080); applyMenuZoom(); }catch(_f){}
       __topClear(); __cleanProfile();
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.24',what:'with the raid clock switched OFF the boarding window is the full 30 seconds and the call line does not say the clock runs out first; with the clock on at 12 seconds left the window is 11 (2026-09-06 in-raid audit)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: this fixture cannot deploy';
     if(typeof tryExtractTick!=='function'||typeof tickExtractPoints!=='function') return 'SKIP: no extraction tick in this build';
     var bad=[], warn='runs out '+'first', warn2='closes in '+'two minutes';
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       // THE CLOCK OFF, as Settings leaves it, BEFORE the raid is built: no seconds, the count at zero, and no ring with a closing time.
       CFG.raidSec=0;
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       var g=__state(), p=g.player, Z=null, i;
       if(g.timeLeft!==0) bad.push('control: with the clock off the raid was built with '+g.timeLeft+' seconds on it');
       for(i=0;i<(g.zones||[]).length&&!Z;i++) if(g.zones[i].open) Z=g.zones[i];
       if(!Z) return 'SKIP: no open extraction ring';
       for(i=0;i<g.zones.length;i++) if(g.zones[i].closeAt!==undefined) bad.push('with the clock off ring '+i+' carries a closing time of '+g.zones[i].closeAt);
       p.x=Z.x+70; p.y=Z.y; p.downed=false; keys={}; window.__lastSay=null;
       var line=null, first=null;
       for(i=0;i<20&&(Z.beaconT===null||Z.beaconT===undefined);i++){ tryExtractTick(0.1,true); if(first===null) first=String(window.__lastSay||''); if(Z.beaconT!==null&&Z.beaconT!==undefined) line=String(window.__lastSay||''); }
       if(first&&first.indexOf(warn2)>=0) bad.push('with the clock off the drop warned that a ring '+warn2);
       if(Z.beaconT===null||Z.beaconT===undefined) bad.push('control: holding E two seconds at the ring edge did not call for extraction');
       if(line===null||line.indexOf('Pulled')!==0) bad.push('control: the call did not say Pulled (said "'+String(line).slice(0,60)+'")');
       else if(line.indexOf(warn)>=0) bad.push('with the clock off the call still says the raid clock '+warn);
       // EXTRACTION LANDS: one tick past the end of the inbound wait sets the window.
       Z.beaconT=0.001; Z.hold=null; Z.holdMax=null; g.active=Z;
       tickExtractPoints(0.016);
       if(Z.hold===null||Z.hold===undefined) bad.push('control: the landing set no boarding window');
       else if(Math.abs(Z.holdMax-30)>0.001) bad.push('with the clock off the boarding window is '+Z.holdMax+' seconds, not 30');
       // CONTROL: with the clock on and 12 seconds left, the window is 11.
       CFG.raidSec=540; g.timeLeft=12; g.raidLen=540;
       Z.beaconT=0.001; Z.hold=null; Z.holdMax=null;
       tickExtractPoints(0.016);
       if(Z.hold===null||Z.hold===undefined||Math.abs(Z.holdMax-11)>0.001) bad.push('control: with the clock on at 12 s left the window is '+Z.holdMax+', not 11');
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{ keys={}; try{ __resetCfg(); }catch(_c){} try{ var g2=__state(); if(g2&&!g2.over){ g2.player.downed=false; __endRaid('extract'); } }catch(_e){} __topClear(); __cleanProfile(); }
     return bad.length?bad.join('; '):null; }},
  {v:'12.23',what:'going down lets go of a cooking grenade: the throw leaves the hand with the fuse it has burned, no COOKING clock is painted over the man on the floor, and the self-revive does not stand him up holding a live cook (2026-09-06 in-raid audit)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__textTrace&&window.__frame)) return 'SKIP: this fixture cannot deploy and trace';
     if(typeof damagePlayer!=='function'||typeof startCook!=='function'||typeof selfRevive!=='function'||typeof drawHUD!=='function'||typeof THROWKEYS==='undefined') return 'SKIP: no cook, down or HUD path in this build';
     var bad=[], word='COOK'+'ING';
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       var g=__state(), p=g.player, en=null;
       for(var i=0;i<g.ents.length&&!en;i++) if(g.ents[i].kind==='crawler'&&!g.ents[i].downed) en=g.ents[i];
       // A frag in the pouch and selected, the aim 200 units east; the pin comes out and half a second burns.
       g.pouch.frag=(g.pouch.frag||0)+1; g.tsel=THROWKEYS.indexOf('frag');
       p.downed=false; p.revived=false; p.roll=0; p.iv=0; p.armor=0; p.hp=5; p.cooking=0; p.cookT=0; p.cookKind=null;
       mouse.x=innerWidth/2+200; mouse.y=innerHeight/2;
       var before=g.throws.length;
       if(!startCook()) bad.push('control: the pin did not come out');
       p.cookT=0.5;
       if(!p.cooking) bad.push('control: nothing is cooking');
       damagePlayer(40,en,en?en.kind:'crawler',p.x+20,p.y);
       if(!p.downed) bad.push('control: the hit did not put him down (hp '+p.hp+')');
       if(p.cooking) bad.push('he went down still holding a live cook (cookT '+p.cookT+')');
       var th=g.throws.slice(before);
       if(th.length!==1) bad.push('the grenade did not leave his hand: '+th.length+' throws left it (wanted 1)');
       else{
         if(th[0].kind!=='frag') bad.push('what left his hand was a '+th[0].kind);
         if(Math.abs((th[0].cook||0)-0.5)>0.01) bad.push('the throw forgot the fuse it had burned (cook '+th[0].cook+')');
       }
       var tr=__textTrace(function(){ __frame(0.016); drawHUD(); });
       if(tr.some(function(r){ return r.t.indexOf(word)===0; })) bad.push('a '+word+' clock is still painted over a man on the floor');
       // The one self-revive brings him up empty-handed.
       if(!selfRevive()) bad.push('control: the self-revive was refused');
       if(p.cooking) bad.push('he got up holding the cook he went down with');
       // CONTROL: the same hit with nothing in hand throws nothing.
       p.downed=false; p.revived=false; p.hp=5; p.iv=0; p.roll=0; p.cooking=0; p.cookT=0; p.cookKind=null;
       var before2=g.throws.length;
       damagePlayer(40,en,en?en.kind:'crawler',p.x+20,p.y);
       if(!p.downed) bad.push('control: the second hit did not put him down');
       if(g.throws.length!==before2) bad.push('control: a hit with nothing in hand threw something');
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{
