     for(i=1;i<S.length;i++){ var q=S[i]; var still=(q[3]===0&&q[7]>0&&q[5]>0); if(still){ run++; if(run>worst){ worst=run; at=q[0]; } } else run=0; }
     // Samples are five seconds apart; three in a row standing still with a
