     // CONTROL: it stays centred, and at 1080p it is where it always was.
     if(Math.abs(a.x-960)>4) bad.push('control: at 1080p the message is centred at x='+Math.round(a.x)+', not 960');
     if(Math.abs(b.x-1920)>6) bad.push('control: at 4K the message is centred at x='+Math.round(b.x)+', not 1920');
     // LH carries a fixed 1.5625 factor on top of the monitor scale, so LH(109) lands at 170 at 1080p; measured on v10.18.
     if(a.y<150||a.y>190) bad.push('control: at 1080p the message sits at y='+Math.round(a.y)+', not near 170');
     return bad.length?bad.join('; '):null; }},
  {v:'10.42',what:'the pillager board and the conditions panel move as far as the hand that drags them, and stay on the screen',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(!(window.__hudBox&&window.__deploy&&window.__frame)) return 'SKIP: this fixture cannot read the HUD boxes';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P(); var keep=P2.hud?JSON.parse(JSON.stringify(P2.hud)):null;
     P2.hud={};
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     var g=__state(); if(!g) return 'SKIP: no raid';
     g.ents.length=0; g.player.hp=100000; g.player.maxhp=100000;
     // The board needs a roster to draw at all.
     if(!g.roster||!g.roster.length) g.roster=[{name:'PROBE_4242',val:0,ref:null,out:false,crew:null}];
     function rect(k){ for(var f=0;f<2;f++) __frame(0.016); var b=__hudBox()[k]; return b?{x:b.x,y:b.y,w:b.w,h:b.h}:null; }
     function moved(k,dx,dy){
       P2.hud[k]={}; var a=rect(k); if(!a) return null;
       P2.hud[k]={dx:dx,dy:dy}; var b=rect(k); if(!b) return null;
       P2.hud[k]={};
       return {dx:Math.round(b.x-a.x), dy:Math.round(b.y-a.y), a:a, b:b};
     }
     try{
       // THE FINDING. On v10.41 a 100 pixel drag moved the board 113.
       var r=moved('raiders',100,0);
       if(!r) return 'SKIP: the pillager board did not draw';
       if(Math.abs(r.dx-100)>1) return 'a 100 pixel drag moved the pillager board '+r.dx+' pixels';
       var r2=moved('raiders',0,80);
       if(r2&&Math.abs(r2.dy-80)>1) bad.push('an 80 pixel drag down moved the pillager board '+r2.dy);
       // THE CONDITIONS PANEL, which is anchored at the right edge: drag it left and down.
       var c=moved('cond',-100,0);
       if(!c) bad.push('the conditions panel did not draw');
       else if(Math.abs(c.dx+100)>1) bad.push('a 100 pixel drag left moved the conditions panel '+c.dx);
       var c2=moved('cond',0,60);
       if(c2&&Math.abs(c2.dy-60)>1) bad.push('a 60 pixel drag down moved the conditions panel '+c2.dy);
       // AND THEY STAY ON THE SCREEN: a drag off the edge is held at the edge.
       P2.hud.raiders={dx:9000,dy:9000}; var far=rect('raiders'); P2.hud.raiders={};
       // v9.12's rule: the HANDLE stays on screen, not the whole box; a tall
       // board may hang below the bottom edge with its bar still in reach.
       if(far&&(far.x+far.w>W+2||far.y>H-8||far.y<-2)) bad.push('the pillager board can be dragged off the screen: right '+Math.round(far.x+far.w)+' top '+Math.round(far.y)+' of '+W+'x'+H);
       P2.hud.cond={dx:-9000,dy:9000}; var farc=rect('cond'); P2.hud.cond={};
       if(farc&&(farc.x<-2||farc.y>H-8||farc.y<-2)) bad.push('the conditions panel can be dragged off the screen: left '+Math.round(farc.x)+' top '+Math.round(farc.y));
       // CONTROL: the vitals block, which was right already, still moves 100 for 100.
       var bd=moved('body',100,0);
       if(!bd) bad.push('control: the vitals block did not draw');
       else if(Math.abs(bd.dx-100)>1) bad.push('control: the vitals block moved '+bd.dx+' for a 100 pixel drag');
     } finally {
       P2.hud=keep||{};
     }
     return bad.length?bad.join('; '):null; }},
  {v:'10.41',what:'his words, first batch, read back off the screens: the pause box, the downed line, the abandon button, the Depot and Wirt',
   run:function(){
     var bad=[];
     function txt(id){ var el=document.getElementById(id); return el?(el.textContent||'').replace(/\s+/g,' ').trim():null; }
     function has(id,re,name){ var t=txt(id); if(t===null){ bad.push(name+' is not in the page'); return; } if(!re.test(t)) bad.push(name+' reads "'+t.slice(0,70)+'"'); }
     // THE FINDING. On v10.40 the pause box still said RUN PAUSED.
     var pb=document.querySelector('.pausebox');
     var pbt=pb?(pb.textContent||'').replace(/\s+/g,' '):'';
     if(!pb) return 'SKIP: no pause box in this build';
     if(!/RAID PAUSED/.test(pbt)) return 'the pause box does not say RAID PAUSED, it says "'+pbt.slice(0,40)+'"';
     if(!/E interact/.test(pbt)) bad.push('the pause box controls line does not say E interact');
     if(!/CTRL \/ C crouch toggle/.test(pbt)) bad.push('the pause box does not say CTRL / C crouch toggle');
     if(!/Please provide feedback/.test(pbt)) bad.push('the pause box feedback line is not his');
     has('pausebleed',/YOU ARE DOWNED\./,'the downed line');
     has('pausebleed',/You can extract while downed/,'the downed line');
     // The claim in that line, that extraction while downed is permitted, was
     // read off the extraction prompt table (his run 44) rather than driven here.
     // THE CONFIRM BUTTON IS WRITTEN AT CLICK TIME, with the XP cost; the markup
     // is a placeholder. Click the abandon button once outside a raid to make
     // it write, read it, and click again to put it back.
     var abtn=document.getElementById('abandonbtn'), cb=document.getElementById('confirmabandon');
     if(!abtn||!cb) bad.push('the pause box has no abandon or confirm button');
     else {
       var wasShown=cb.style.display;
       if(cb.style.display!=='none'){ abtn.click(); }
       abtn.click();
       var live=cb.textContent.trim();
       if(!/^YES, ABANDON THIS RUN/.test(live)) bad.push('the live abandon confirm reads "'+live+'"');
       abtn.click();
       cb.style.display=wasShown||'none';
     }
     // THE DEPOT AND WIRT. Wirt's line is drawn from a pool by renderGamble, so
     // the pool must hold his sentence and the drawn line must come from the pool.
     var dep=Array.prototype.filter.call(document.querySelectorAll('.msub'),function(d){ return (/Cosmetics do not impact game mechanics\./).test(d.textContent); }).length;
     if(!dep) bad.push('the Depot does not say cosmetics do not impact game mechanics');
     if(typeof VENDOR_LINES==='undefined'||!VENDOR_LINES.gamble||!VENDOR_LINES.gamble.some(function(l){ return l==='Gamble with Wirt. No refunds, no complaints.'; })) bad.push('Wirt\'s pool of lines does not hold "Gamble with Wirt. No refunds, no complaints."');
     try{ if(typeof renderGamble==='function') renderGamble(); }catch(_rg){}
     var gl=document.getElementById('gamble_line');
     if(!gl) bad.push('Wirt has no line');
     else if(typeof VENDOR_LINES!=='undefined'&&VENDOR_LINES.gamble&&VENDOR_LINES.gamble.indexOf(gl.textContent.trim())<0) bad.push('Wirt says "'+gl.textContent.trim()+'", which is not in his pool');
     var gb=document.getElementById('gamblebtn');
     // v15.05: the button prints its price with a thousands separator (Gamble $2,500), which /2500/ does not match.
     if(gb&&!/2\D?500/.test(gb.textContent)) bad.push('the gamble button reads "'+gb.textContent+'" and the price is 2,500');
     // CONTROL: the three lines he sent back empty are untouched.
     var sn=document.getElementById('termsclear');
     if(!sn||sn.textContent.trim()!=='Sign nothing') bad.push('control: the Sign nothing button changed, and that row came back empty');
     var pn=document.getElementById('pausenote');
     if(!pn||!/crier marked me/.test(pn.getAttribute('placeholder')||'')) bad.push('control: the feedback placeholder changed, and that row came back empty');
     return bad.length?bad.join('; '):null; }},
  {v:'10.40',what:'no building on THE COLD MILE holds a room bigger than a player that nothing can reach, on five seeds, and the guard sees one when it is there',
   run:function(){
     var bad=[];
     if(!(window.__movers&&__movers.buildNav)) return 'SKIP: no buildNav to flood with';
     __pinDPR(1); __forceSize(1920,1080);
     // A fine flood of the finished map, cell 4, from where the player stands.
     // A building is flagged only when the floor nothing reaches spans at least
     // ROOM by ROOM units, which is a space a man could stand in; the slivers
     // behind furniture and the 28 deep niches measured on v10.39 are not.
     var ROOM=32;
     function survey(seed, brick){
       __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:1,seed:seed});
       var g=__state(), B=g.map.buildings||[], W=g.map.walls||[], L=g.map.locked||[];
       var added=0;
       if(brick!==undefined&&B[brick]){
         // THE CONTROL: brick up every doorway in this building's own shell, so
         // its interior is truly unreachable, and require the guard to say so.
         var b0=B[brick], t0=16;
         function segsOn(side){ var out=[]; for(var i=0;i<W.length;i++){ var q=W[i]; if(q.ib!==undefined||q.furn) continue;
           var on=(side===0&&Math.abs(q.y-b0.y)<1)||(side===1&&Math.abs(q.y+q.h-(b0.y+b0.h))<1)||(side===2&&Math.abs(q.x-b0.x)<1)||(side===3&&Math.abs(q.x+q.w-(b0.x+b0.w))<1);
           if(!on) continue;
           if(side<2){ if(q.x<b0.x-1||q.x+q.w>b0.x+b0.w+1) continue; out.push([q.x,q.x+q.w]); }
           else { if(q.y<b0.y-1||q.y+q.h>b0.y+b0.h+1) continue; out.push([q.y,q.y+q.h]); } }
           out.sort(function(p,q2){ return p[0]-q2[0]; }); return out; }
         for(var side=0;side<4;side++){
           var sg=segsOn(side), lo=(side<2)?b0.x:b0.y, hi=(side<2)?b0.x+b0.w:b0.y+b0.h, cur=lo;
           for(var k=0;k<=sg.length;k++){
             var nx=(k<sg.length)?sg[k][0]:hi;
             if(nx-cur>2){
               if(side===0) W.push({x:cur,y:b0.y,w:nx-cur,h:t0,d:0,probeBrick:1});
               else if(side===1) W.push({x:cur,y:b0.y+b0.h-t0,w:nx-cur,h:t0,d:0,probeBrick:1});
               else if(side===2) W.push({x:b0.x,y:cur,w:t0,h:nx-cur,d:0,probeBrick:1});
               else W.push({x:b0.x+b0.w-t0,y:cur,w:t0,h:nx-cur,d:0,probeBrick:1});
               added++;
             }
             if(k<sg.length) cur=Math.max(cur,sg[k][1]);
           }
         }
       }
       var WW=g.map.cols*g.map.cw, HH=g.map.rows*g.map.ch, F=4, t=16, i, x, y;
       var fw=Math.ceil(WW/F), fh=Math.ceil(HH/F), blk=new Uint8Array(fw*fh);
       for(i=0;i<W.length;i++){
         var w=W[i];
         var x0=Math.max(0,Math.floor(w.x/F)), x1=Math.min(fw-1,Math.floor((w.x+w.w)/F));
         var y0=Math.max(0,Math.floor(w.y/F)), y1=Math.min(fh-1,Math.floor((w.y+w.h)/F));
         for(y=y0;y<=y1;y++) for(x=x0;x<=x1;x++) blk[y*fw+x]=1;
       }
       var pl=g.player, seed0=Math.floor(pl.y/F)*fw+Math.floor(pl.x/F);
       var seen=new Uint8Array(fw*fh), st=[seed0]; seen[seed0]=1;
       while(st.length){
         var c=st.pop(), cy=(c/fw)|0, cx=c%fw;
         if(cx>0&&!seen[c-1]&&!blk[c-1]){ seen[c-1]=1; st.push(c-1); }
         if(cx<fw-1&&!seen[c+1]&&!blk[c+1]){ seen[c+1]=1; st.push(c+1); }
         if(cy>0&&!seen[c-fw]&&!blk[c-fw]){ seen[c-fw]=1; st.push(c-fw); }
         if(cy<fh-1&&!seen[c+fw]&&!blk[c+fw]){ seen[c+fw]=1; st.push(c+fw); }
       }
       function inLk(px,py){ for(var l=0;l<L.length;l++){ var K=L[l]; if(px>K.x&&px<K.x+K.w&&py>K.y&&py<K.y+K.h) return true; } return false; }
       var rooms=[], widest=0;
       for(var b=0;b<B.length;b++){
         var bb=B[b], minx=1e9,maxx=-1,miny=1e9,maxy=-1, un=0;
         for(y=Math.floor((bb.y+t)/F); y<=Math.floor((bb.y+bb.h-t)/F); y++)
           for(x=Math.floor((bb.x+t)/F); x<=Math.floor((bb.x+bb.w-t)/F); x++){
             var ii=y*fw+x;
             if(blk[ii]||seen[ii]) continue;
             if(inLk(x*F+F/2,y*F+F/2)) continue;
             un++; if(x<minx)minx=x; if(x>maxx)maxx=x; if(y<miny)miny=y; if(y>maxy)maxy=y;
           }
         if(!un) continue;
         var bw=(maxx-minx+1)*F, bh=(maxy-miny+1)*F;
         widest=Math.max(widest, Math.min(bw,bh));
         if(bw>=ROOM&&bh>=ROOM) rooms.push(b+'('+bw+'x'+bh+')');
       }
       // put the bricks back in the bag: the map is shared by the checks after this one
       if(added){ for(i=W.length-1;i>=0;i--) if(W[i].probeBrick) W.splice(i,1); }
       return {buildings:B.length, rooms:rooms, narrowest:widest, ents:g.ents.length};
     }
     // THE GUARD, on the fingerprint seed and the four seeds that showed the
     // most unreachable floor on v10.39 (4, 2, 9, 6).
     var seeds=[4242,4,2,9,6], found=[];
     for(var si=0;si<seeds.length;si++){
       var r=survey(seeds[si]);
       if(r.buildings!==84) return 'SKIP: THE COLD MILE did not build its 84 buildings at seed '+seeds[si];
       if(r.rooms.length) found.push('seed '+seeds[si]+': '+r.rooms.join(', '));
       if(seeds[si]===4242&&r.ents!==374) bad.push('the entity count at seed 4242 reads '+r.ents+', not the 374 the fingerprint holds');
     }
     if(found.length) bad.push('rooms a player could stand in that nothing can reach: '+found.join('; '));
     // THE CONTROL: brick building 0 on the fingerprint seed and require the guard to name it.
     var ctl=survey(4242, 0);
     if(!ctl.rooms.some(function(x){ return x.indexOf('0(')===0; }))
       bad.push('control: building 0 was bricked up on purpose and the guard did not see it (it saw: '+(ctl.rooms.join(', ')||'nothing')+')');
     return bad.length?bad.join('; '):null; }},
  {v:'10.39',what:'a player is asked once, in plain words, whether run reports may be sent, and only when there is somewhere to send them',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(!window.__hubEnter) return 'SKIP: this build cannot be driven into the Undercroft';
     var md=document.getElementById('sharemodal');
     // THE FINDING. On v10.38 there was no question anywhere; a friend was never asked.
     if(!md) return 'there is no question window; a friend on itch is never asked whether reports may be sent';
     if(typeof maybeShareAsk!=='function') return 'there is a window but no code that asks';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P(); var keep={shareAsked:P2.shareAsked,shareRuns:P2.shareRuns,welcomed:P2.welcomed};
     var drop0=PUBLIC_DROP;
     function rowText(){ var b=document.getElementById('set_share'); var row=b&&b.parentNode; return row?(row.textContent||''):''; }
     try{
       // WITH NO ADDRESS THERE IS NO QUESTION.
       PUBLIC_DROP=null; P2.shareAsked=undefined; P2.shareRuns=false; P2.welcomed=1;
       maybeShareAsk();
       if(md.classList.contains('on')) bad.push('asked with nowhere to send the report');
       // WITH AN ADDRESS, ASKED, IN WORDS THAT SAY WHERE A NO GOES.
       PUBLIC_DROP='https://probe-4242.example/run';
       maybeShareAsk();
       if(!md.classList.contains('on')) bad.push('not asked although an address exists');
       var txt=(md.textContent||'').replace(/\s+/g,' ');
       if(!/Downloads/.test(txt)) bad.push('the question does not say where a report goes if they say no');
       if(!/Settings/.test(txt)) bad.push('the question does not say it can be changed in Settings');
       var yes=document.getElementById('shareyes'), no=document.getElementById('shareno');
       if(!yes||!no) bad.push('the window lacks its YES or its CLOSE');
       if(no&&no.textContent.trim()!=='CLOSE') bad.push('the way out reads "'+no.textContent.trim()+'" and not CLOSE');
       if(no&&!no.hasAttribute('data-esc')) bad.push('ESC does not reach the CLOSE');
       // YES MEANS YES, ONCE.
       if(yes) yes.click();
       if(P2.shareRuns!==true) bad.push('YES did not switch sharing on');
       if(P2.shareAsked!==1) bad.push('YES did not mark the question answered');
       if(md.classList.contains('on')) bad.push('the window stayed open after YES');
       maybeShareAsk();
       if(md.classList.contains('on')) bad.push('asked a second time after an answer');
       // CLOSE MEANS NO, AND IT STILL COUNTS AS ANSWERED.
       P2.shareAsked=undefined; P2.shareRuns=false;
       maybeShareAsk();
       if(!md.classList.contains('on')) bad.push('not asked on a profile that has not answered');
       if(no) no.click();
       if(P2.shareRuns!==false) bad.push('CLOSE switched sharing on');
       if(P2.shareAsked!==1) bad.push('CLOSE did not mark the question answered');
       if(md.classList.contains('on')) bad.push('the window stayed open after CLOSE');
       // IT COMES THROUGH THE WELCOME, so a character that already has its pack meets it on arrival.
       P2.shareAsked=undefined; P2.welcomed=1;
       if(typeof maybeWelcome==='function'){
         maybeWelcome();
         if(!md.classList.contains('on')) bad.push('arriving with the pack already answered did not ask');
         md.classList.remove('on');
       }
       // THE SETTINGS HINT SAYS WHAT IS TRUE, both ways.
       if(typeof renderSettings==='function'){
         __hubEnter(); renderSettings();
         var h1=rowText();
         if(!/sends/.test(h1)) bad.push('with an address the Settings row still says nothing is sent: "'+h1.slice(0,90)+'"');
         PUBLIC_DROP=null; renderSettings();
         var h2=rowText();
         if(!/no upload address/.test(h2)) bad.push('with no address the Settings row claims to send: "'+h2.slice(0,90)+'"');
       }
       // AND THE CARD SAYS THE QUESTION EXISTS, so a friend who closed it knows where to find it.
       if(window.__words&&typeof __words.whatsnew==='function'){ var wl=__words.whatsnew().lines||[]; if(!wl.some(function(l){ return (/RUN REPORTS MAY BE SENT/).test(l); })) bad.push('the WHAT IS NEW card does not say the question exists'); }
       // CONTROL: the welcome pack window is still there.
       if(!document.getElementById('welcomemodal')) bad.push('control: the welcome pack window is gone');
     } finally {
       PUBLIC_DROP=drop0; md.classList.remove('on');
       P2.shareAsked=keep.shareAsked; P2.shareRuns=keep.shareRuns; P2.welcomed=keep.welcomed;
       var _m=document.querySelectorAll('.modal.on'); for(var _i=0;_i<_m.length;_i++) _m[_i].classList.remove('on');
     }
     return bad.length?bad.join('; '):null; }},
  {v:'10.38',what:'the WHAT IS NEW card is current, opens with what an alpha is, and names what a friend will meet first',
   run:function(){
     var bad=[];
     if(!window.__words||typeof __words.whatsnew!=='function') return 'SKIP: this build cannot report its card';
     var wn=__words.whatsnew();
     var vNow=parseFloat(String(wn.build||'0').replace(/[^0-9.]/g,''))||0;
     var vCard=parseFloat(String(wn.ver||'0').replace(/[^0-9.]/g,''))||0;
     // THE FINDING. On v10.37 the card stood at v10.22, fifteen builds behind.
     // v10.42: the card moves only when the list changes (v2.77), so the rule
     // is the v9.19 gate, fifteen builds, not two; two tripped on nothing.
     if(vNow-vCard>0.15) return 'the card is at v'+wn.ver+' against a build at v'+wn.build+', so a friend reads news that is '+Math.round((vNow-vCard)*100)+' builds old';
     var L=wn.lines||[];
     if(L.length<10) bad.push('the card has only '+L.length+' lines');
     if(!/ALPHA/.test(L[0]||'')) bad.push('the first line does not say it is an alpha: "'+String(L[0]).slice(0,60)+'"');
     [['WELCOME PACK',/WELCOME PACK/],['the fourteen racks',/FOURTEEN RACKS/],['net lifetime earnings',/NET LIFETIME EARNINGS/],['the tactical belt',/TACTICAL BELT/]].forEach(function(w){
       if(!L.some(function(l){ return w[1].test(l); })) bad.push('no line names '+w[0]);
     });
     // ONE WORD PER THING: the belt is named as the belt, never as a hotbar on its own.
     L.forEach(function(l,i){ if(/HOTBAR/.test(l)&&!/TACTICAL BELT/.test(l)) bad.push('line '+(i+1)+' calls the belt a hotbar'); });
     // NO DASHES, his rule for every line he reads.
     L.forEach(function(l,i){ if(/[\u2013\u2014]/.test(l)) bad.push('line '+(i+1)+' carries a dash'); });
     // CONTROL: the card is still the thing the hub shows once per version.
     if(typeof WNSEEN==='undefined') bad.push('control: the once-per-load latch is gone');
     return bad.length?bad.join('; '):null; }},
  {v:'10.37',what:'an uncaught error or an unhandled rejection is written to the profile and the run report, counted, capped, and told once',
   run:function(){
     var bad=[];
     var P2=__P();
     // THE FINDING. On v10.36 the profile had no list and nothing listened.
     if(!Array.isArray(P2.crashes)) return 'the profile has no crashes list, so a fault on a friend machine records nothing';
     if(typeof buildExport!=='function') return 'SKIP: no run report builder in this build';
     var keep=P2.crashes.slice(); P2.crashes.length=0;
     var tag='probe alpha crash 4242';
     function fire(m){ window.dispatchEvent(new ErrorEvent('error',{message:m,error:new Error(m),filename:'probe.js',lineno:7})); }
     fire(tag);
     if(P2.crashes.length!==1) bad.push('one uncaught error made '+P2.crashes.length+' entries');
     var c=P2.crashes[0]||{};
     if(c.msg!==tag) bad.push('the entry says "'+c.msg+'" and not the message thrown');
     if(c.v!==VER) bad.push('the entry is stamped v'+c.v+' and not v'+VER);
     if(!c.screen||c.screen==='?') bad.push('the entry names no screen: "'+c.screen+'"');
     if(!/Error|probe\.js|:\d+:\d+/.test(c.where||'')) bad.push('the entry carries no stack and no file: "'+c.where+'"');   // v14.64: a line and column location counts (v14.51)
     var rep=buildExport();
     if(rep.indexOf('CRASHES')<0||rep.indexOf(tag)<0) bad.push('the run report does not carry the crash');
     // THE SAME FAULT EVERY FRAME COUNTS ON ONE LINE, it does not fill the list.
     fire(tag); fire(tag); fire(tag);
     if(P2.crashes.length!==1) bad.push('the same message four times made '+P2.crashes.length+' entries');
     if((P2.crashes[0]||{}).n!==4) bad.push('the repeat count reads '+(P2.crashes[0]||{}).n+' and not 4');
     // A REJECTION IS CAUGHT TOO.
     var rtag='probe alpha rejection 4242';
     var pr=Promise.reject(new Error(rtag)); pr.catch(function(){});
     try{ window.dispatchEvent(new PromiseRejectionEvent('unhandledrejection',{promise:pr,reason:new Error(rtag)})); }
     catch(_e){ bad.push('could not raise a rejection event: '+_e.message); }
     if(!P2.crashes.some(function(x){ return x.kind==='rejection'&&x.msg===rtag; })) bad.push('an unhandled rejection was not recorded');
     // THE LIST KEEPS ITS NEWEST TWELVE.
     // v14.64: the probes differ in a letter, because since v14.49 messages differing only in a number are one crash.
     for(var i=0;i<20;i++) fire('probe distinct '+String.fromCharCode(97+i)+' 4242');
     if(P2.crashes.length>12) bad.push('the list grew to '+P2.crashes.length+', past twelve');
     var newest=P2.crashes[P2.crashes.length-1]||{};
     if(newest.msg!=='probe distinct t 4242') bad.push('the cap dropped the newest entry rather than the oldest: last is "'+newest.msg+'"');
     // A RESOURCE ERROR WITH NO MESSAGE AND NO ERROR IS NOT A CRASH.
     var before=P2.crashes.length; window.dispatchEvent(new ErrorEvent('error',{}));
     if(P2.crashes.length!==before) bad.push('an empty error event was recorded as a crash');
     // CONTROL: the report still opens with its header, so the section was added, not substituted.
     if(rep.indexOf('FLIGHT RECORDER')<0) bad.push('control: the report lost its header');
     P2.crashes.length=0; keep.forEach(function(x){ P2.crashes.push(x); });
     return bad.length?bad.join('; '):null; }},
