     if(typeof UISCALES==='undefined'||typeof uiScale!=='function'||typeof zoomTarget!=='function') return 'SKIP: this build has no HUD size steps';
     function wheel(el,dy,ctrl){
       var ev=new WheelEvent('wheel',{deltaY:dy,deltaMode:0,bubbles:true,cancelable:true,ctrlKey:!!ctrl});
       el.dispatchEvent(ev); return ev;
     }
     function idxOf(v){ for(var i=0;i<UISCALES.length;i++) if(Math.abs(UISCALES[i]-v)<0.001) return i; return -1; }
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P(); var keepScale=P2.uiScale, keepMZ=P2.menuZoom;
     // Start from the middle of the table so a step either way is possible.
     P2.uiScale=UISCALES[Math.floor(UISCALES.length/2)]; P2.menuZoom=1;
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     var g=__state(); if(!g) return 'SKIP: no raid';
     function done(v){ P2.uiScale=keepScale; P2.menuZoom=keepMZ; try{ applyMenuZoom(); }catch(_e){} return v; }
     // ONE: ctrl-wheel up in a raid is one HUD step up, and the world does not zoom.
     var i0=idxOf(uiScale()), z0=zoomTarget();
     wheel(cv,-100,true);
     var i1=idxOf(uiScale()), z1=zoomTarget();
     if(i1!==i0+1) bad.push('ctrl-wheel up moved the HUD size from step '+i0+' to '+i1+', not one step up');
     if(Math.abs(z1-z0)>1e-6) bad.push('ctrl-wheel also zoomed the world, '+z0.toFixed(3)+' to '+z1.toFixed(3));
     // and one step back down.
     wheel(cv,100,true);
     if(idxOf(uiScale())!==i0) bad.push('ctrl-wheel down did not step the HUD back');
     // CONTROL: the plain wheel still zooms and leaves the HUD alone.
     var zb=zoomTarget(), ib=idxOf(uiScale());
     wheel(cv,-100,false);
     if(!(zoomTarget()>zb)) bad.push('control: the plain wheel no longer zooms in');
     if(idxOf(uiScale())!==ib) bad.push('control: the plain wheel changed the HUD size');
     // TWO: the Undercroft. Wirt's list made scrollable, the wheel over it must
     // scroll, not size the menus. The floor beside it must still size them.
     var shut=['stagemodal','sectormodal','outcome','title','pausebox'], was={};
     for(var si=0;si<shut.length;si++){ var se=document.getElementById(shut[si]); was[shut[si]]=!!(se&&se.classList.contains('on')); if(se) se.classList.remove('on'); }
     var hub=document.getElementById('hub'), hubWas=!!(hub&&hub.classList.contains('on'));
     function restore(v){
       for(var q=0;q<shut.length;q++){ var e2=document.getElementById(shut[q]); if(!e2) continue; if(was[shut[q]]) e2.classList.add('on'); else e2.classList.remove('on'); }
       if(hub){ if(hubWas) hub.classList.add('on'); else hub.classList.remove('on'); }
       var gm2=document.getElementById('gamblemodal'); if(gm2) gm2.classList.remove('on');
       return done(v);
     }
     __showScreen('hub'); if(hub) hub.classList.add('on');
     var gm=document.getElementById('gamblemodal'), list=document.getElementById('gamblelist');
     if(!gm||!list||typeof renderGamble!=='function') return restore(bad.length?bad.join('; '):'SKIP: no Wirt list to scroll');
     P2.credits=50000; P2.gambleLog=[]; for(var k=0;k<40;k++) P2.gambleLog.push('scrap');
     gm.classList.add('on');
     try{ renderGamble(); }catch(e1){ return restore('renderGamble threw: '+e1); }
     if(!(list.scrollHeight-list.clientHeight>2)) return restore(bad.length?bad.join('; '):'SKIP: the list did not overflow, so there is nothing to scroll');
     var row=list.firstElementChild||list;
     var mz0=(__P().menuZoom||1);
     var ev1=wheel(row,100,false);
     var mz1=(__P().menuZoom||1);
     if(Math.abs(mz1-mz0)>1e-6) bad.push('the wheel over the scrolling list resized the menus, '+mz0+' to '+mz1);
     if(ev1.defaultPrevented) bad.push('the wheel over the scrolling list was swallowed, so it cannot scroll');
     // CONTROL: on the floor, with no scrollable box under the pointer, the wheel
     // still sizes the menus.
     gm.classList.remove('on');
     var floor=document.getElementById('hub')||document.body;
     var mz2=(__P().menuZoom||1);
     wheel(floor,-100,false);   // v10.22: upward, because the size floors at 1.0 and this check starts there
     var mz3=(__P().menuZoom||1);
     if(Math.abs(mz3-mz2)<1e-6) bad.push('control: the wheel on the Undercroft floor no longer sizes the menus');
     return restore(bad.length?bad.join('; '):null); }},
  {v:'9.94',what:'Wirt has two counters, per roll and a five minute Limited Time Offer that names its item',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout, nothing is measured';
     if(typeof renderGamble!=='function'||typeof wirtLotKey!=='function') return 'SKIP: no Wirt in this build';
     // Needles from halves: this page embeds the source it tests.
     var AGO=[' a',' go'].join(''), CARRY=['carry it ','out of here'].join(''), HOUR=['for the ','hour'].join('');
     __pinDPR(1); __forceSize(1920,1080); __cleanProfile();
     var P2=__P(); P2.credits=50000; P2.gambleLog=[]; P2.stash=[];
     var gm=document.getElementById('gamblemodal'); if(!gm) return 'SKIP: no Wirt panel in the page';
     var wasOn=gm.classList.contains('on'); gm.classList.add('on');
     try{ renderGamble(); }catch(e0){ gm.classList.toggle('on',wasOn); return 'renderGamble threw: '+e0; }
     var txt=gm.textContent||'';
     // ONE: the two strings he named.
     if(txt.indexOf('$2,500 per roll')<0&&txt.indexOf('$2500 per roll')<0) bad.push('the wallet line does not say $2,500 per roll');
     if(new RegExp('\\$2,?500'+AGO+'\\b').test(txt)) bad.push('the screen still says $2,500'+AGO);
     if(txt.indexOf(CARRY)>=0) bad.push('the sentence about not having to '+CARRY+' is still there');
     // TWO: the offer card says three things and nothing else.
     var lot=document.getElementById('wirtlot');
     if(!lot) bad.push('no offer card');
     else {
       var lines=[].map.call(lot.querySelectorAll('span[style*="display:block"],span[style*="display: block"]'),function(s){ return s.textContent.trim(); });
       // v10.03, his answer 38: four lines, the item's name second.
       if(lines.length!==4) bad.push('the offer card has '+lines.length+' lines, ['+lines.join(' | ')+'], not four');
       else {
         if(lines[0]!=='Limited Time Offer') bad.push('line one reads ['+lines[0]+']');
         var headName=(ITEMS[(wirtLotKey()||[])[0]]||{}).name||'';
         if(!headName||lines[1].indexOf(headName)<0) bad.push('line two does not name the item '+headName+', it reads ['+lines[1]+']');
         if(!/^Worth \$[\d,]+$/.test(lines[2])) bad.push('line three reads ['+lines[2]+']');
         if(!/^New item in \d+ minutes?$/.test(lines[3])) bad.push('line four reads ['+lines[3]+']');
         var m=/New item in (\d+)/.exec(lines[3]); if(m&&+m[1]>5) bad.push('the card promises a new item in '+m[1]+' minutes, more than five');
       }
       if((lot.textContent||'').indexOf(HOUR)>=0) bad.push('the card still says on the counter '+HOUR);
     }
     // THREE: the delineation, measured. Two boxes, one headed THE GAMBLE and
     // one LIMITED TIME OFFER, each with its own border, and clear air between.
     var sg=document.getElementById('wirtsec_gamble'), so=document.getElementById('wirtsec_offer');
     if(!sg||!so) bad.push('the two sections are not there as their own boxes');
     else {
       var rg=sg.getBoundingClientRect(), ro=so.getBoundingClientRect();
       var cg=getComputedStyle(sg), co=getComputedStyle(so);
       // A computed border width is divided by the modal's zoom, so 1px reads
       // 0.769px at zoom 1.3: test the style and a positive width, not 1.
       if(cg.borderTopStyle!=='solid'||!(parseFloat(cg.borderTopWidth)>0)||co.borderTopStyle!=='solid'||!(parseFloat(co.borderTopWidth)>0)) bad.push('a section has no border of its own');
       if(cg.borderTopColor===co.borderTopColor) bad.push('both sections share one border colour, so nothing tells them apart');
       var gap=ro.top-rg.bottom;
       if(!(gap>=8)) bad.push('the two sections are '+Math.round(gap)+' px apart, which is not clear air');
       if(!/THE GAMBLE/.test(sg.textContent)||!/LIMITED TIME OFFER/.test(so.textContent)) bad.push('the section heads are not THE GAMBLE and LIMITED TIME OFFER');
       if(!sg.querySelector('#gamblebtn')) bad.push('the Gamble button is not inside THE GAMBLE');
       if(!so.querySelector('#wirtlot')) bad.push('the offer card is not inside LIMITED TIME OFFER');
     }
     // FOUR: the clock. Same key across one five-minute window, a different
     // draw is at least possible across it, and the countdown never exceeds it.
     var t0=Math.floor(1750000000000/300000)*300000, K0=wirtLotKey(t0)[0];
     if(wirtLotKey(t0+299000)[0]!==K0) bad.push('the offer changed inside its own five minutes');
     var changed=false; for(var q=1;q<=6;q++) if(wirtLotKey(t0+q*300000)[0]!==K0){ changed=true; break; }
     if(!changed) bad.push('the offer never changed across thirty minutes');
     if(wirtLotLeft(t0+1000)>300) bad.push('the countdown is '+wirtLotLeft(t0+1000)+' seconds, longer than five minutes');
     if(!wasOn) gm.classList.remove('on');
     return bad.length?bad.join('; '):null; }},
  {v:'9.93',what:'the pause screen and the legends say RMB aims down sights, and the compact row stays inside its column',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout, nothing is drawn';
     if(!(window.__textTrace&&window.__deploy&&window.__frame&&window.__hudBox))
       return 'SKIP: this fixture cannot read what the HUD draws';
     // Needles from halves: this page embeds the source it tests.
     var STEADY=['steady',' aim'].join('');
     // ONE: the pause box, which is what he named.
     var pb=document.getElementById('pausebox'), pbt=(pb&&pb.textContent)||'';
     if(!/RMB\s+aim down sights/i.test(pbt)) bad.push('the pause screen does not say RMB aim down sights');
     if(new RegExp('RMB\\s+'+STEADY,'i').test(pbt)) bad.push('the pause screen still says RMB '+STEADY);
     // TWO: the two legend tables, read as data.
     function rowVal(tbl,key){
       if(!tbl) return null;
       for(var a=0;a<tbl.length;a++){
         var r=tbl[a];
         if(r&&r.length===2&&typeof r[1]==='string'){ if(r[0]===key) return r[1]; }
         else if(r&&r[1]&&r[1].length) for(var b=0;b<r[1].length;b++) if(r[1][b][0]===key) return r[1][b][1];
       }
       return null;
     }
     var LEG=(typeof LEGEND!=='undefined')?LEGEND:null, MINI=(typeof LEGEND_MINI!=='undefined')?LEGEND_MINI:null;
     var fv=rowVal(LEG,'RMB'), mv=rowVal(MINI,'RMB');
     if(fv===null||mv===null) bad.push('this fixture could not read the RMB row from the legends');
     else {
       if(fv!=='aim down sights') bad.push('the full legend RMB row reads ['+fv+']');
       if(mv!=='sights') bad.push('the compact legend RMB row reads ['+mv+']');
     }
     // THREE, the control that keeps this honest: the compact row as DRAWN must
     // end inside the legend panel. The whole phrase measures wider than the
     // column, which is the reason the compact row is one word.
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     var g=__state(); if(!g) return 'SKIP: no raid';
     var keepLeg=g.legendOn; g.legendOn=1;
     for(var f=0;f<10;f++) __frame(0.016);
     var tr=__textTrace(function(){ __frame(0.016); });
     var box=(__hudBox()||{}).legend;
     g.legendOn=keepLeg;
     if(!box) return 'SKIP: the compact legend drew no panel box';
     var rowsOut=[], sawRmb=false;
     for(var i=0;i<tr.length;i++){
       var d=tr[i];
       if(d.t==='RMB') sawRmb=true;
       if(d.y<box.y||d.y>box.y+box.h||d.x<box.x-1) continue;
       if(d.align==='right') continue;
       if(d.x+d.w>box.x+box.w+0.5) rowsOut.push(d.t+' ends '+Math.round(d.x+d.w-(box.x+box.w))+' past the panel edge');
     }
     if(!sawRmb) bad.push('control: the compact legend never drew an RMB row');
     if(rowsOut.length) bad.push('compact legend text runs out of its panel: '+rowsOut.join(', '));
     return bad.length?bad.join('; '):null; }},
  {v:'9.92',what:'C and CTRL toggle crouch, one press down and the next up, and the legends say so',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(!(window.__keysRef&&window.__loop&&window.__deploy)) return 'SKIP: this fixture cannot hold a key';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     var g=__state(); if(!g) return 'SKIP: no raid';
     var p=g.player; p.iv=99; p.hp=100000; p.maxhp=100000; p.stam=100;
     g.ents.length=0;                      // nobody to bump into or be shot by
     var ox=p.x, oy=p.y;
     // A key table read FRESH every time: showScreen replaces the object, and a
     // latched key from an earlier probe has made ENTER look broken twice.
     function K(){ return __keysRef(); }
     function clearKeys(){ var k=K(); for(var q in k) if(k.hasOwnProperty(q)) k[q]=false; }
     // Walk one direction for a fixed number of real-loop frames and measure how
     // far he got. Crouch is a speed multiplier of .52 in the movement step, so
     // the ratio between a held crouch key and none is the whole finding.
     // v10.07: crouch is a toggle. A press through the real handler turns it
     // on; a second press after the walk turns it off again.
     function press(code){
       try{ document.dispatchEvent(new KeyboardEvent('keydown',{code:code,key:code,bubbles:true,cancelable:true})); }catch(_e1){}
       try{ document.dispatchEvent(new KeyboardEvent('keyup',{code:code,key:code,bubbles:true,cancelable:true})); }catch(_e2){}
     }
     function walk(dir,held){
       clearKeys();
       p.x=ox; p.y=oy; p.vx=0; p.vy=0; p.roll=0; p.downed=0; p.ads=false; p.stam=100; p.stamLock=0; p.stamRelease=0;
       g.crouchTog=false; g.sprintTog=false;
       if(held) press(held);
       var k=K(); k[dir]=true;
       var t0=performance.now();
       for(var f=0;f<24;f++) __loop(t0+f*16.7);
       clearKeys();
       if(held) press(held);
       return Math.sqrt((p.x-ox)*(p.x-ox)+(p.y-oy)*(p.y-oy));
     }
     // Find a direction he can actually move in from the spawn.
     var dirs=['KeyD','KeyA','KeyS','KeyW'], dir=null, base=0;
     for(var d=0;d<dirs.length;d++){ var dd=walk(dirs[d],null); if(dd>40){ dir=dirs[d]; base=dd; break; } }
     if(!dir) return 'SKIP: the player could not walk from the spawn in any direction';
     var withCtrl=walk(dir,'ControlLeft'), withC=walk(dir,'KeyC');
     var rC=withC/base, rCtrl=withCtrl/base;
     // THE FINDING. On v9.91 KeyC was autoloot, so he walked at full speed with C
     // held: ratio one. Crouched he walks at about half.
     if(rC>0.8) bad.push('with C held he still walked at '+Math.round(rC*100)+'% of full speed, so C is not crouch');
     // CONTROL: CTRL still crouches, and crouch is still slower than walking, so
     // the finding above could not pass by movement being broken outright.
     if(rCtrl>0.8) bad.push('control: with CTRL held he walked at '+Math.round(rCtrl*100)+'%, so CTRL no longer crouches');
     if(Math.abs(rC-rCtrl)>0.08) bad.push('C and CTRL crouch at different speeds, '+Math.round(rC*100)+'% against '+Math.round(rCtrl*100)+'%');
     // v10.07: and the second press stands him up. After walk() pressed twice
     // he must be at full speed with no key held at all.
     g.crouchTog=false; press('KeyC'); press('KeyC');
     var again=walk(dir,null);
     if(again/base<0.8) bad.push('two presses of C left him crouched, walking at '+Math.round(again/base*100)+'%');
     // C must not still flip autoloot. Press it through the real key handler.
     var was=!!__P().autoloot;
     try{ document.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyC',key:'c',bubbles:true,cancelable:true})); }catch(_e1){}
     try{ document.dispatchEvent(new KeyboardEvent('keyup',{code:'KeyC',key:'c',bubbles:true,cancelable:true})); }catch(_e2){}
     if(!!__P().autoloot!==was) bad.push('pressing C still toggles autoloot');
     clearKeys();
     // The surfaces that name the key: the pause box, and both legends.
     var pb=document.getElementById('pausebox'), pbt=(pb&&pb.textContent)||'';
     if(!/CTRL\s*\/\s*C\s+crouch/i.test(pbt)) bad.push('the pause screen does not say CTRL / C crouch');
     var LEG=(typeof LEGEND!=='undefined')?LEGEND:null, MINI=(typeof LEGEND_MINI!=='undefined')?LEGEND_MINI:null;
     function rowKey(tbl,word){
       if(!tbl) return null;
       for(var a=0;a<tbl.length;a++){
         var r=tbl[a];
         if(r&&r.length===2&&typeof r[1]==='string'){ if(new RegExp('^'+word).test(r[1])) return r[0]; }
         else if(r&&r[1]&&r[1].length) for(var b=0;b<r[1].length;b++) if(new RegExp('^'+word).test(r[1][b][1])) return r[1][b][0];
       }
       return null;
     }
     var fk=rowKey(LEG,'crouch'), mk=rowKey(MINI,'crouch');
     if(fk===null||mk===null) bad.push('this fixture could not read the crouch row from the legends');
     else {
       if(!/CTRL\s*\/\s*C/i.test(fk)) bad.push('the full legend crouch row reads ['+fk+']');
       if(!/CTRL\s*\/\s*C/i.test(mk)) bad.push('the compact legend crouch row reads ['+mk+']');
     }
     return bad.length?bad.join('; '):null; }},
  {v:'9.91',what:'a downed pillager takes more than one Scav Pistol round to finish',
   run:function(){
     var bad=[];
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     var g=__state(); if(!g) return 'SKIP: no raid';
     var p=g.player; p.iv=99; p.hp=100000; p.maxhp=100000;
     // One hostile pillager, nothing else, on open ground beside the player.
     var R=null;
     for(var i=0;i<g.ents.length;i++){ var e=g.ents[i]; if(e.kind==='raider'&&!e.merc){ R=e; break; } }
     if(!R) return 'SKIP: no pillager on this map and seed';
     g.ents.length=0; g.ents.push(R);
     var PD=19;                                  // the Scav Pistol, WEAPONS.pistol.dmg
     function stage(){
       R.x=p.x+120; R.y=p.y; R.hostile=true; R.downed=0; R.finished=false; R.roll=0;
       R.hp=1; R.maxhp=R.maxhp||100; R.state='chase'; R.tx=p.x; R.ty=p.y;
       if(g.ents.indexOf(R)<0) g.ents.push(R);
       g.bullets.length=0;
     }
     // A round fired by the player, placed on the man and resolved by the game's
     // own bullet loop, so the damage takes the path a real shot takes, weak
     // points, armour and all. It is the pistol's 19.
     function shoot(){
       g.bullets.push({x:R.x-6,y:R.y,vx:1180,vy:0,dmg:PD,life:0.2,player:true,owner:p,tint:'#ffd48a'});
       for(var f=0;f<4;f++) __loop(performance.now()+f*16.7);
     }
     function present(){ return g.ents.indexOf(R)>=0; }
     // Down him with the game's own down path: one round on a man at one health.
     stage(); shoot();
     if(!present()) return 'SKIP: the first round removed him outright, so no down happened to test';
     if(!R.downed) return 'SKIP: the man was not downed by a round at one health, raiderDown may be off';
     var hpDown=R.hp;
     // THE FINDING. On v9.90 a downed pillager had e.hp=1, so the very next round
     // of anything finished him. His note: more than one Scav Pistol shot.
     shoot();
     if(!present())
       bad.push('one Scav Pistol round finished a downed pillager, he went down with '+hpDown+' health');
     else if(!R.downed)
       bad.push('the second round changed his state to ['+R.state+'] rather than leaving him down');
     // How many it actually takes, counting from the down.
     var rounds=1, guard=0;
     while(present()&&guard++<12){ shoot(); rounds++; }
     if(present()) bad.push('twelve pistol rounds did not finish a downed pillager, he is still there at '+Math.round(R.hp)+' health');
     if(rounds<2) bad.push('it took '+rounds+' round to finish him, which is not more than one');
     // CONTROL ONE: the dial is live and the old behaviour is one setting away.
     // If the finding above passed for some other reason, this arm exposes it.
     __cfg({raiderDownHp:1});
     stage(); shoot();
     if(!present()||!R.downed) bad.push('control: could not stage a downed man with the dial at 1');
     else { shoot(); if(present()) bad.push('control: with raiderDownHp at 1 a single round did not finish him, so the dial is not what decides this'); }
     __cfg({raiderDownHp:40});
     // CONTROL TWO: a Longshot does not now need three rounds. Anything heavier
     // than a pistol must still drop him in two.
     stage(); shoot();
     if(present()&&R.downed){
       g.bullets.push({x:R.x-6,y:R.y,vx:1180,vy:0,dmg:60,life:0.2,player:true,owner:p,tint:'#ffd48a'});
       for(var f2=0;f2<4;f2++) __loop(performance.now()+f2*16.7);
       if(present()) bad.push('control: a 60 damage round did not finish a downed man at 40 health');
     }
     return bad.length?bad.join('; '):null; }},
  {v:'9.90',what:'the backpack has one name on every surface that names it, and the pad legend says tactical belt',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout, nothing is drawn';
     if(!(window.__textTrace&&window.__deploy&&window.__frame))
       return 'SKIP: this fixture cannot read what the HUD draws';
     // NEEDLES FROM HALVES, never whole: this page embeds the source it tests.
     var BAG=['b','ag'].join(''), INV=['inven','tory'].join(''), KIT=['Kit is ','full'].join('');
     var BELT=['bel','t'].join(''), TABINV=['TAB  ','INVENTORY'].join('');
     function lc(s){ return String(s||'').toLowerCase(); }
     function isWord(text,w){ return new RegExp('(^|[^a-z])'+w+'([^a-z]|$)','i').test(String(text||'')); }
