           for(x=Math.floor((bb.x+t)/F); x<=Math.floor((bb.x+bb.w-t)/F)&&!un; x++){
             var ii=y*fw+x;
             if(blk[ii]||seen[ii]) continue;
             if(inLk(x*F+F/2,y*F+F/2)) continue;
