  {v:'9.77',what:'a building is not condemned because a doorway fell badly across the grid',
   run:function(){
     var bad=[];
     if(!(window.__movers&&__movers.buildNav)) return 'SKIP: no buildNav to flood with';
     __pinDPR(1); __forceSize(1920,1080);
